function tPluralSame(noun){const P=TCH.plSame||(TCH.plSame=(()=>{const s=new Set();try{allCards().forEach(c=>{const x=String(c.de).match(/^(der|die|das)\s+([A-ZÄÖÜ][^\s,;(]+)$/);if(x&&/^(-|—|=|die\s+\S+?)$/.test(String(c.pl||"").trim())&&(String(c.pl).trim()==="-"||String(c.pl).trim().endsWith(x[2])))s.add(x[2])})}catch(e){}return s})());return P.has(noun)}
