    demo=`<div class="dg-row">${dg(esc(f.adv),"dg-p1","Position 1")}${dg(esc(f.verb),"dg-verb","Verb · 2")}${dg(esc(f.subj),"dg-subj","Subjekt")}${dg("…","dg-rest","Rest")}</div><div class="dg-row dg-bad">${dg(esc(f.adv),"","1")}${dg(esc(f.subj),"dg-x","✗")}${dg(esc(f.verb),"dg-x","")}</div>`;
