// 11.4: "Fast!" only for a real typo – one word, one letter, not an ending or a participle form (getrinkt ≠ getrunken)
function nearTypo(got,ans){const T=x=>String(x||"").toLowerCase().replace(/[.,!?;:"„“]/g," ").trim().split(/\s+/).filter(Boolean);const a=T(got),b=T(ans);if(a.length!==b.length)return false;const d=[];for(let i=0;i<a.length;i++)if(a[i]!==b[i])d.push([a[i],b[i]]);if(d.length!==1)return false;const [x,y]=d[0];
  const U=w=>w.replace(/ä/g,"a").replace(/ö/g,"o").replace(/ü/g,"u").replace(/ß/g,"ss");if(U(x)===U(y)&&x.length!==y.length)return true;if(U(x)===U(y))return true;
  if(/^ge/.test(y)&&/^ge/.test(x))return false;if(Math.min(x.length,y.length)<4)return false;
  let p=0;while(p<x.length&&p<y.length&&x[p]===y[p])p++;if(p>=Math.min(x.length,y.length)-2){const E=/^(e|en|er|es|em|n|s|t|st|et|te|ten)?$/;if(E.test(x.slice(p))&&E.test(y.slice(p)))return false} // an ending difference is grammar, not a typo
  const lev=(s,t)=>{const m=[...Array(t.length+1).keys()];for(let i=1;i<=s.length;i++){let pr=m[0];m[0]=i;for(let j=1;j<=t.length;j++){const tmp=m[j];m[j]=Math.min(m[j]+1,m[j-1]+1,pr+(s[i-1]===t[j-1]?0:1));pr=tmp}}return m[t.length]};return lev(x,y)<=1}

// ================= CITRUS HUB + GOOGLE DRIVE (11.1) =================
// Mephisto joins the Citrus hub (claude/hub-contract.md): one shared Google Cloud project, no backend.
//   My Apps/hub/mephisto/state.json   — the learner's whole progress (Drive is the master copy; every device syncs it)
//   My Apps/hub/mephisto/status.json  — the hub snapshot every app writes (summary, today, week, asks, pending, extra)
//   My Apps/hub/citrus/plan.json (fallback hub/scheduler/) — Citrus's answer: today's blocks per app (read, shown on Heute)
//   Google Calendar                   — shift events → duty days (streak protection, planning)
// Sign-in: Google Identity Services token client (same client id as the other apps, pasted once in Settings).
// Only in the installed app / GitHub Pages copy: the claude.ai artifact origin cannot sign in to Google.
const HUB={APP:"mephisto",ROOT:"My Apps",SCOPES:"openid email https://www.googleapis.com/auth/drive https://www.googleapis.com/auth/calendar.events",DRIVE:"https://www.googleapis.com/drive/v3",UPLOAD:"https://www.googleapis.com/upload/drive/v3",FOLDER:"application/vnd.google-apps.folder",
  KEY:"mephisto_google",IDS:"mephisto_drive_ids",busy:false,last:{},fp:"",statusAt:0,stateAt:0,timer:null,shiftWords:/dienst|schicht|shift|nacht|night|notaufnahme|\bD[12]\b|\bN\d?\b|on[- ]call|bereitschaft/i};
const hubCan=()=>typeof IS_PWA!=="undefined"&&IS_PWA&&window.isSecureContext;
function gAuth(){try{return JSON.parse(localStorage.getItem(HUB.KEY)||"null")}catch(e){return null}}
function gSet(a){try{if(a)localStorage.setItem(HUB.KEY,JSON.stringify(a));else localStorage.removeItem(HUB.KEY)}catch(e){}}
function gToken(){const a=gAuth();return a&&a.token&&a.exp>Date.now()+30000?a.token:null}
function gConf(){S.google=S.google||{};return S.google}
const syncedAt=()=>{try{return localStorage.getItem("mephisto_synced_at")||""}catch(e){return ""}};const setSynced=v=>{try{localStorage.setItem("mephisto_synced_at",v||"")}catch(e){}};
const isoLocal=iso=>{if(!iso)return "";const d=new Date(iso);return keyOf(d)+"T"+pad(d.getHours())+":"+pad(d.getMinutes())};
function localChangedSince(iso){const ev=S.events||[];if(!ev.length)return false;if(!iso)return true;const last=ev[ev.length-1];return (last.d+"T"+last.t)>isoLocal(iso)}
function gDevice(){const u=navigator.userAgent;return /iPhone|iPad/.test(u)?"iPhone":/Android/.test(u)?"Android":/Windows/.test(u)?"PC":/Mac/.test(u)?"Mac":"Gerät"}
// ---- sign-in (GIS token client, loaded on demand)
let gisP=null;function gisLoad(){if(window.google&&google.accounts&&google.accounts.oauth2)return Promise.resolve();if(gisP)return gisP;gisP=new Promise((res,rej)=>{const s=document.createElement("script");s.src="https://accounts.google.com/gsi/client";s.async=true;s.onload=()=>res();s.onerror=()=>{gisP=null;rej(new Error("gsi"))};document.head.appendChild(s)});return gisP}
async function gConnect(o){o=o||{};const cid=(gConf().clientId||"").trim();if(!cid)throw new Error("no_client");await gisLoad();
  return new Promise((res,rej)=>{let done=false;const tc=google.accounts.oauth2.initTokenClient({client_id:cid,scope:HUB.SCOPES,callback:async r=>{if(done)return;done=true;if(!r||!r.access_token){rej(new Error((r&&r.error)||"denied"));return}
      const a={token:r.access_token,exp:Date.now()+Math.max(60,(+r.expires_in||3600)-60)*1000,email:""};try{const u=await fetch("https://www.googleapis.com/oauth2/v3/userinfo",{headers:{Authorization:"Bearer "+a.token}});if(u.ok)a.email=(await u.json()).email||""}catch(e){}gSet(a);res(a)},error_callback:e=>{if(done)return;done=true;rej(new Error(e&&e.type||"popup"))}});
    tc.requestAccessToken({prompt:o.silent?"":"consent"});if(o.silent)setTimeout(()=>{if(!done){done=true;rej(new Error("silent_timeout"))}},8000)})}
async function gEnsure(){if(gToken())return gToken();const a=gAuth();if(!a)throw new Error("signed_out");try{await gConnect({silent:true});return gToken()}catch(e){gSet(null);throw new Error("signed_out")}}
async function gFetch(url,init){const t=await gEnsure();init=Object.assign({},init||{});init.headers=Object.assign({Authorization:"Bearer "+t},init.headers||{});const r=await fetch(url,init);if(r.status===401){gSet(null);throw new Error("signed_out")}if(!r.ok){throw new Error("http_"+r.status)}return r}
async function gJSON(url,init){const r=await gFetch(url,init);return r.status===204?null:r.json()}
// ---- Drive: folders (cached per device), files
const idsGet=()=>{try{return JSON.parse(localStorage.getItem(HUB.IDS)||"{}")}catch(e){return {}}};const idsSet=o=>{try{localStorage.setItem(HUB.IDS,JSON.stringify(o))}catch(e){}};
const q=s=>String(s).replace(/\\/g,"\\\\").replace(/'/g,"\\'");
async function dList(parent,name,folders){const parts=["trashed = false"];if(parent)parts.push(`'${q(parent)}' in parents`);if(name)parts.push(`name = '${q(name)}'`);if(folders)parts.push(`mimeType = '${HUB.FOLDER}'`);
  return (await gJSON(`${HUB.DRIVE}/files?`+new URLSearchParams({q:parts.join(" and "),fields:"files(id,name,mimeType,modifiedTime,size)",pageSize:"50",spaces:"drive",orderBy:"modifiedTime desc"})))?.files||[]}
async function dFolder(path,retry,noCreate){const key=path.join("/");const ids=idsGet();if(ids[key]&&!retry)return ids[key];let parent=null;let acc=[];
  for(const name of path){acc.push(name);const k=acc.join("/");if(ids[k]&&!retry){parent=ids[k];continue}let f=(await dList(parent,name,true))[0];if(!f&&noCreate)return null;if(!f)f=await gJSON(`${HUB.DRIVE}/files?fields=id`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name,mimeType:HUB.FOLDER,parents:parent?[parent]:[]})});ids[k]=f.id;parent=f.id}
  idsSet(ids);return parent}
async function dFile(folderId,name){return (await dList(folderId,name))[0]||null}
async function dRead(fileId){const r=await gFetch(`${HUB.DRIVE}/files/${encodeURIComponent(fileId)}?alt=media`);return r.json()}
async function dWrite(folderId,name,obj,fileId){const b="mephisto"+Date.now();const meta=fileId?{name}:{name,parents:[folderId]};const body=`--${b}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(meta)}\r\n--${b}\r\nContent-Type: application/json\r\n\r\n${JSON.stringify(obj)}\r\n--${b}--`;
  const url=fileId?`${HUB.UPLOAD}/files/${encodeURIComponent(fileId)}?uploadType=multipart&fields=id,modifiedTime`:`${HUB.UPLOAD}/files?uploadType=multipart&fields=id,modifiedTime`;return gJSON(url,{method:fileId?"PATCH":"POST",headers:{"Content-Type":`multipart/related; boundary=${b}`},body})}
async function hubFolder(retry){return dFolder([HUB.ROOT,"hub",HUB.APP],retry)}
async function withRetry(fn){try{return await fn(false)}catch(e){if(/http_404/.test(e.message))return fn(true);throw e}}
// ---- 1. state.json: Drive is the master copy of the learner's progress
function stateFingerprint(){const o=Object.assign({},S);delete o.savedAt;delete o.today;let s=JSON.stringify(o);let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return h+":"+s.length}
async function hubPullState(o){o=o||{};const g=gConf();if(g.syncState===false||!gAuth())return null;return withRetry(async retry=>{const folder=await hubFolder(retry);const f=await dFile(folder,"state.json");if(!f){HUB.last.state="noch keine Sicherung";return null}const remote=await dRead(f.id);if(!remote||remote.v!==2)return null;
    const rAt=remote.savedAt||f.modifiedTime||"";HUB.last.remoteAt=rAt;const mine=syncedAt();
    const localEmpty=!Object.keys(S.cards).length&&!Object.keys(S.lessons).length&&!(S.events||[]).length;
    if(rAt&&rAt!==mine){if(localEmpty||o.force||!localChangedSince(mine)){const keep=Object.assign({},g);adopt(validate(remote),"cloud");S.google=Object.assign({},S.google||{},keep);saveNow();setSynced(rAt);HUB.stateAt=Date.now();HUB.fp=stateFingerprint();HUB.conflict=null;HUB.last.state="geladen "+fmtTime(rAt);try{applyPrefs();buildDict();rerender()}catch(e){}logEvent("sync","Fortschritt von Google Drive geladen");return "pulled"}
      HUB.last.state="Konflikt";HUB.conflict={at:rAt};return "conflict"}
    HUB.last.state=HUB.last.state||"aktuell";return "same"})}
async function hubPushState(force){const g=gConf();if(!g.syncState||!gAuth())return;const fp=stateFingerprint();if(!force&&fp===HUB.fp)return;if(!force&&Date.now()-HUB.stateAt<120000)return;if(HUB.busy)return;HUB.busy=true;
  try{await withRetry(async retry=>{const folder=await hubFolder(retry);const f=await dFile(folder,"state.json");S.savedAt=new Date().toISOString();const snap=Object.assign({},S);delete snap.today;await dWrite(folder,"state.json",snap,f&&f.id);setSynced(S.savedAt);HUB.fp=fp;HUB.stateAt=Date.now();HUB.conflict=null;HUB.last.state="gesichert "+fmtTime(S.savedAt);HUB.last.err=""});saveNow()}
  catch(e){HUB.last.err=hubErr(e)}finally{HUB.busy=false;hubPaint()}}
const fmtTime=iso=>{try{const d=new Date(iso);return fmtDate(keyOf(d))+" "+pad(d.getHours())+":"+pad(d.getMinutes())}catch(e){return ""}};
function hubErr(e){const m=String(e&&e.message||e);return m==="signed_out"?"Anmeldung nötig":m==="no_client"?"Client-ID fehlt":/http_403/.test(m)?"Kein Zugriff (Drive-API / Origin prüfen)":/http_/.test(m)?"Google antwortet "+m.slice(5):/popup|denied/.test(m)?"Anmeldung abgebrochen":m==="gsi"?"Google-Script nicht geladen (offline?)":m}
// ---- 2. status.json: the hub snapshot (contract shape)
function hubStatus(){const t=todayKey();const T=S.today&&S.today.date===t?S.today:null;const L=S.log[t]||{};const est=typeof levelEstimate==="function"?levelEstimate():{stufe:"?",pct:0,next:"?"};const due=dueKeys().length;
  const mon=(()=>{const [y,m,d]=t.split("-").map(Number);const dt=new Date(y,m-1,d);const wd=(dt.getDay()+6)%7;return addDays(t,-wd)})();const days=[];let done=0;for(let i=0;i<7;i++){const d=addDays(mon,i);const l=S.log[d]||{};const trained=!!l.act;if(trained)done++;const shift=!!(S.shifts||{})[d];days.push({date:d,shift:shift?"Dienst":"",trained,planned:d>=t&&!trained,usual:true,slot:shift?"tough":"free"})}
  const target=S.restDays?6:7;const steps=T?T.steps.filter(s=>!s.done).map(s=>STRAND[s.t].name):[];const left=T?Math.round(S.minutes*(steps.length/Math.max(1,T.steps.length))):S.minutes;
  const asks=days.filter(d=>d.date>=t&&!d.trained).map(d=>({date:d.date,title:"Mephisto: Sitzung"+(d.date===t&&T?" (Rest: "+steps.join(", ")+")":""),minutes:d.date===t?left:S.minutes,slot:d.shift?"before":"free"}));
  const pending=[];if(due)pending.push(due+" Karten fällig");const coach=typeof coachItems==="function"?(coachItems()||[]).slice(0,2).map(c=>c.title||"").filter(Boolean):[];pending.push(...coach);
  const go=(S.exams||{}).goethe,fs=(S.exams||{}).fsp;const w=weekNumber();const ph=typeof phaseOf==="function"?phaseOf(w).name:"";
  const summary=`${T&&T.steps.every(s=>s.done)?"Sitzung heute fertig":T?steps.length+" von "+T.steps.length+" Schritten offen":"Heutige Sitzung noch nicht begonnen"} · ${minutesOn(t)} Min. heute · ${due} Karten fällig · Stufe ${est.stufe}${est.pct?" ("+est.pct+" % zu "+est.next+")":""}.`;
  return {app:HUB.APP,version:typeof APP_VERSION!=="undefined"?APP_VERSION:"",device:gDevice(),updatedAt:new Date().toISOString(),summary,
    today:{date:t,done:!!(T&&T.steps.every(s=>s.done)),items:[].concat(L.session?[{title:"Heutige Sitzung",minutes:minutesOn(t)}]:[],L.rev?[{title:"Karten",cards:L.rev,ok:L.ok||0}]:[],L.les?[{title:"Lektionen",count:L.les}]:[],L.exam?[{title:"Prüfungsaufgaben",count:L.exam}]:[])},
    week:{start:mon,end:addDays(mon,6),done,target,need:Math.max(0,target-done),days},
    next:{title:T&&steps.length?"Sitzung: "+steps[0]:"Heutige Sitzung",minutes:left},asks,pending:pending.slice(0,5),
    extra:{stufe:est.stufe,toNext:est.pct,next:est.next,streak:streak(),week:w,of:WEEKS.length,phase:ph,wordsKnown:knownWords(),cardsDue:due,minutesToday:minutesOn(t),exams:{goethe:go||null,fsp:fs||null},url:typeof APP_URL!=="undefined"?APP_URL:""}}}
function statusFingerprint(st){const o=Object.assign({},st);delete o.updatedAt;return JSON.stringify(o)}
async function hubPushStatus(force){const g=gConf();if(g.publish===false||!gAuth())return;const st=hubStatus();const fp=statusFingerprint(st);if(!force&&fp===HUB.statusFp)return;if(!force&&Date.now()-HUB.statusAt<300000)return;
  try{await withRetry(async retry=>{const folder=await hubFolder(retry);const f=await dFile(folder,"status.json");await dWrite(folder,"status.json",st,f&&f.id)});HUB.statusFp=fp;HUB.statusAt=Date.now();HUB.last.status=fmtTime(st.updatedAt);HUB.last.err=""}catch(e){HUB.last.err=hubErr(e)}hubPaint()}
// ---- 3. plan.json from Citrus: today's blocks for Mephisto
async function hubPullPlan(){const g=gConf();if(!gAuth())return;try{HUB.last.plan="";let f=null;for(const dir of ["citrus","scheduler"]){const folder=await dFolder([HUB.ROOT,"hub",dir],false,true);if(folder)f=await dFile(folder,"plan.json");if(f)break}if(!f){HUB.plan=null;return}const p=await dRead(f.id);HUB.plan=p;S.citrusPlan={at:new Date().toISOString(),blocks:planBlocks(p)};saveSoon();hubPaint()}catch(e){HUB.last.plan=hubErr(e)}}
function planBlocks(p){const out=[];const t=todayKey();const walk=(x,d)=>{if(!x||d>6)return;if(Array.isArray(x)){x.forEach(y=>walk(y,d+1));return}if(typeof x!=="object")return;const app=String(x.app||x.id||x.name||"").toLowerCase();
    if(app==="mephisto"&&(x.minutes||x.start||x.time||x.title)){const date=x.date||x.day||t;if(!x.date||x.date===t||d<=2)out.push({date,start:x.start||x.time||x.at||"",minutes:+x.minutes||+x.duration||0,title:x.title||x.label||"Mephisto"})}
    if(x.mephisto&&typeof x.mephisto==="object")walk(Object.assign({app:"mephisto"},x.mephisto),d+1);Object.keys(x).forEach(k=>{if(k!=="mephisto"&&typeof x[k]==="object")walk(x[k],d+1)})};walk(p,0);return out.slice(0,4)}
// ---- 4. calendar: shift events → duty days
async function hubPullShifts(){const g=gConf();if(g.calendar===false||!gAuth())return;try{const cal=g.calendarId||"primary";const t=todayKey();const min=new Date(addDays(t,-7)+"T00:00:00").toISOString(),max=new Date(addDays(t,21)+"T00:00:00").toISOString();
    const r=await gJSON(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(cal)}/events?`+new URLSearchParams({timeMin:min,timeMax:max,singleEvents:"true",maxResults:"250",orderBy:"startTime"}));const items=(r&&r.items)||[];let n=0;S.shifts=S.shifts||{};
    items.forEach(ev=>{const title=(ev.summary||"")+" "+(ev.description||"");if(!HUB.shiftWords.test(title))return;const s=ev.start||{};const d=(s.date||(s.dateTime||"").slice(0,10));if(!d)return;const hour=s.dateTime?new Date(s.dateTime).getHours():9;const night=/nacht|night|\bN\d?\b/i.test(title)||hour>=18;if(!S.shifts[d]){S.shifts[d]=1;n++}if(night){const nx=addDays(d,1);if(!S.shifts[nx]){S.shifts[nx]=1;n++}}});
    HUB.last.cal=items.length+" Termine, "+n+" neue Diensttage";if(n){saveSoon();logEvent("sync",n+" Diensttage aus dem Kalender übernommen")}}catch(e){HUB.last.err=hubErr(e)}hubPaint()}
// ---- orchestration
async function hubSync(force){if(!hubCan()||!gAuth())return;if(HUB.syncing)return;HUB.syncing=true;hubPaint();try{await gEnsure();const r=await hubPullState({force:false});if(r!=="pulled"&&r!=="conflict")await hubPushState(force);await hubPushStatus(force);await hubPullPlan();await hubPullShifts();HUB.last.sync=fmtTime(new Date().toISOString());HUB.last.err=HUB.last.err||""}catch(e){HUB.last.err=hubErr(e)}finally{HUB.syncing=false;hubPaint()}}
function hubSchedule(){if(!hubCan()||!gAuth())return;clearTimeout(HUB.timer);HUB.timer=setTimeout(()=>{hubPushState(false);hubPushStatus(false)},90000)}
ACT.hubConnect=async()=>{const g=gConf();const inp=$(".hub-cid");if(inp){g.clientId=inp.value.trim();saveSoon()}if(!g.clientId)return toast("Zuerst die Client-ID eintragen");try{toast("Google öffnet sich …");await gConnect({});g.syncState=g.syncState!==false;g.publish=g.publish!==false;g.calendar=g.calendar!==false;saveSoon();toast("Verbunden: "+(gAuth().email||"Google"));await hubSync(true)}catch(e){toast(hubErr(e))}hubPaint()};
ACT.hubSync=()=>hubSync(true);
ACT.hubSignOut=()=>{gSet(null);HUB.last={};toast("Abgemeldet");hubPaint()};
ACT.hubUseRemote=async()=>{await hubPullState({force:true});HUB.conflict=null;hubPaint()};
ACT.hubKeepLocal=async()=>{HUB.conflict=null;setSynced(HUB.last.remoteAt||"");await hubPushState(true);hubPaint()};
ACT.hubToggle=el=>{const g=gConf();g[el.dataset.k]=el.checked;saveSoon()};
ACT.hubCal=el=>{gConf().calendarId=el.value.trim()||"primary";saveSoon()};
function hubHTML(){const a=gAuth();const g=gConf();const L=HUB.last;if(!hubCan())return `<div class="card stack s"><h3>Google & Citrus</h3><p class="muted ui" style="font-size:.9rem">Google-Anmeldung geht nur in der installierten App (mephisto-deutsch.github.io). Dort wird dein Fortschritt auf Google Drive gesichert und mit Citrus geteilt.${IS_PWA?"":" Hier in claude.ai: Fortschritt per Backup-Datei mitnehmen."}</p></div>`;
  return `<div class="card stack s hub-card"><div class="row between"><h3>Google & Citrus</h3>${a?`<span class="pill good">${esc(a.email||"verbunden")}</span>`:'<span class="pill">nicht verbunden</span>'}</div>
   ${a?"":`<label class="f">Client-ID (aus dem Cloud-Projekt „Citrus apps“, dieselbe wie in Yuzu/Orange)<input class="hub-cid" placeholder="…apps.googleusercontent.com" value="${esc(g.clientId||"")}"></label><small class="muted ui">Im Cloud-Projekt muss <b>https://mephisto-deutsch.github.io</b> als autorisierter JavaScript-Ursprung eingetragen sein.</small><div class="row"><button class="primary" data-act="hubConnect">Mit Google verbinden</button></div>`}
   ${a?`<div class="list"><label class="li" style="cursor:pointer"><span class="t"><b class="ui">Fortschritt auf Drive</b><small>My Apps/hub/mephisto/state.json – jedes Gerät lädt den neuesten Stand</small></span><input type="checkbox" data-act="hubToggle" data-k="syncState" ${g.syncState!==false?"checked":""} style="width:24px;min-height:24px"></label>
    <label class="li" style="cursor:pointer"><span class="t"><b class="ui">Status für Citrus</b><small>status.json: Zusammenfassung, Woche, Zeitwünsche, offene Punkte</small></span><input type="checkbox" data-act="hubToggle" data-k="publish" ${g.publish!==false?"checked":""} style="width:24px;min-height:24px"></label>
    <label class="li" style="cursor:pointer"><span class="t"><b class="ui">Dienste aus dem Kalender</b><small>Schicht-Termine werden Diensttage (Kerze geschützt, Citrus plant drumherum)</small></span><input type="checkbox" data-act="hubToggle" data-k="calendar" ${g.calendar!==false?"checked":""} style="width:24px;min-height:24px"></label></div>
    <label class="f">Kalender-ID<input value="${esc(g.calendarId||"primary")}" data-act="hubCal" onchange="ACT.hubCal(this)"></label>
    <div class="hub-st muted ui" style="font-size:.85rem">${L.err?`<span class="no">${esc(L.err)}</span><br>`:""}Fortschritt: ${esc(L.state||"–")} · Status: ${esc(L.status||"–")} · Kalender: ${esc(L.cal||"–")}${S.citrusPlan&&S.citrusPlan.blocks.length?`<br>Citrus plant: ${S.citrusPlan.blocks.map(b=>esc((b.start?b.start+" ":"")+(b.minutes?b.minutes+" Min.":b.title))).join(", ")}`:""}</div>
    ${HUB.conflict?`<div class="tip"><b>Konflikt:</b> Auf Drive liegt ein neuerer Stand (${esc(fmtTime(HUB.conflict.at))}), und hier wurde seitdem auch gelernt.<div class="row" style="margin-top:.5rem"><button class="sm" data-act="hubUseRemote">Drive-Stand übernehmen</button><button class="sm" data-act="hubKeepLocal">Diesen Stand behalten</button></div></div>`:""}
    <div class="row wrap"><button class="sm" data-act="hubSync" ${HUB.syncing?"disabled":""}>${HUB.syncing?"Synchronisiert …":ic("download")+" Jetzt synchronisieren"}</button><button class="sm ghost" data-act="hubSignOut">Abmelden</button></div>`:""}</div>`}
function hubPaint(){const c=$(".hub-card");if(c){const d=document.createElement("div");d.innerHTML=hubHTML();c.replaceWith(d.firstElementChild)}const w=$(".weg .hub-line");if(w)w.innerHTML=hubLine()}
function hubLine(){if(!hubCan())return "";const a=gAuth();if(!a)return `<span class="muted ui">Citrus: <button class="sm ghost" data-act="hubOpen">Google verbinden</button></span>`;const b=(S.citrusPlan||{}).blocks||[];const today=b.filter(x=>!x.date||x.date===todayKey());return `<span class="muted ui">Citrus${today.length?": heute "+today.map(x=>esc((x.start?x.start+" · ":"")+(x.minutes?x.minutes+" Min.":x.title))).join(", "):" plant noch nicht"}${HUB.last.sync?" · Sync "+esc(HUB.last.sync.slice(-5)):""}</span>`}
ACT.hubOpen=()=>{go("me");setTimeout(()=>{const b=$('[data-act=meSeg][data-k=set]');if(b)b.click();setTimeout(()=>{const c=$(".hub-card");if(c)c.scrollIntoView({behavior:"smooth",block:"center"})},200)},50)};
// settings card + Heute line
(function(){MOD.after("meSettings","hub",function(el){const inst=[...el.querySelectorAll(".card")].find(c=>/Installiert|Installieren|App installieren/.test(c.textContent));const d=document.createElement("div");d.innerHTML=hubHTML();const card=d.firstElementChild;if(inst)inst.after(card);else el.prepend(card)});
  MOD.after("viewHome","hub",function(m){const w=m.querySelector(".weg");if(w&&!w.querySelector(".hub-line")){const l=document.createElement("div");l.className="hub-line";l.innerHTML=hubLine();w.appendChild(l)}})})();
// hooks: stamp saves, schedule uploads, sync on open/return, force after a finished session
(function(){const _sn=saveNow;saveNow=function(){S.savedAt=new Date().toISOString();_sn();hubSchedule()};
  const _fs=typeof finishSession==="function"?finishSession:null;if(_fs)finishSession=function(){_fs();setTimeout(()=>{hubPushState(true);hubPushStatus(true)},800)};
  document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden"){hubPushState(false);hubPushStatus(false)}else if(hubCan()&&gAuth()&&Date.now()-HUB.stateAt>600000)hubSync(false)});
  window.addEventListener("pagehide",()=>{hubPushState(false)});
  if(hubCan()&&gAuth())setTimeout(()=>hubSync(false),1500);
  if(!S.google)S.google={};})();

// ================= LABS, TOOLS & UTILITIES (11.2) =================
// Üben → Labore: Konjugator · Deklinations-Lab · Satzbaukasten · Zahlen-Umrechner · Arztbrief-Werkstatt ·
// Aussprache-Labor · Wörterbuch · Lernplan-Rechner. Plus Wort des Tages and "Nur 5 Minuten" on Heute, deep links.
const LABS=[["konj","Konjugator","Jedes Verb in allen Formen, zum Anhören","type"],["dekl","Deklinations-Lab","Artikel, Fall, Zahl – die Form leuchtet auf","grid"],["satz","Satzbaukasten","Vorfeld · Verb · Mitte · Ende – bau und prüfe","pen"],["zahl","Zahlen-Umrechner","Zahl → Wort, Uhrzeit, Datum, Preis, RR","timer"],["brief","Arztbrief-Werkstatt","Stichpunkte → Arztbrief im Nominalstil","steth"],["laut","Aussprache-Labor","Minimalpaare hören und nachsprechen","ear"],["dict","Wörterbuch","Alle Wörter: suchen, filtern, hören","book"],["plan","Lernplan-Rechner","Prüfungstermin → Wörter und Lektionen pro Tag","target"]];
ACT.labs=()=>{const box=Focus.open({title:"Labore",sub:"tools you can touch"});box.innerHTML=`<div class="stack s"><p class="muted">Werkzeuge zum Ausprobieren: nichts wird benotet, alles kann angehört werden. Halte ein Wort für die Übersetzung.</p><div class="tiles">${LABS.map(l=>`<button class="tile" data-act="lab" data-k="${l[0]}"><span class="ic">${ic(l[3])}</span><b>${l[1]}</b><small>${l[2]}</small></button>`).join("")}</div></div>`};
ACT.lab=el=>{const k=el.dataset.k;const L=LABS.find(x=>x[0]===k);if(!L)return;Focus.close(true);const box=Focus.open({title:L[1],sub:L[2],onClose:()=>{}});({konj:labKonj,dekl:labDekl,satz:labSatz,zahl:labZahl,brief:labBrief,laut:labLaut,dict:labDict,plan:labPlan})[k](box)};
// ---- Konjugator
// Konjugator-only verbs (core A1 verbs and clinical verbs missing from CONJ); separable forms stored joined (anrufe → rufe … an)
const CONJ_EXTRA=[["mögen", "to like", ["mag", "magst", "mag", "mögen", "mögt", "mögen"], ["mochte", "mochtest", "mochte", "mochten", "mochtet", "mochten"], "hat gemocht", "Ich mag den Nachtdienst nicht besonders.", "I don't particularly like night shifts."], ["dürfen", "to be allowed to, may", ["darf", "darfst", "darf", "dürfen", "dürft", "dürfen"], ["durfte", "durftest", "durfte", "durften", "durftet", "durften"], "hat gedurft", "Sie dürfen heute noch nichts essen.", "You're not allowed to eat anything yet today."], ["sollen", "to be supposed to", ["soll", "sollst", "soll", "sollen", "sollt", "sollen"], ["sollte", "solltest", "sollte", "sollten", "solltet", "sollten"], "hat gesollt", "Sie sollen die Tablette morgens nehmen.", "You're supposed to take the tablet in the morning."], ["essen", "to eat", ["esse", "isst", "isst", "essen", "esst", "essen"], ["aß", "aßest", "aß", "aßen", "aßt", "aßen"], "hat gegessen", "Wann haben Sie zuletzt gegessen?", "When did you last eat?"], ["fahren", "to drive, to go (by vehicle)", ["fahre", "fährst", "fährt", "fahren", "fahrt", "fahren"], ["fuhr", "fuhrst", "fuhr", "fuhren", "fuhrt", "fuhren"], "ist gefahren", "Der Rettungswagen fährt in die Uniklinik.", "The ambulance is driving to the university hospital."], ["laufen", "to run, to walk", ["laufe", "läufst", "läuft", "laufen", "lauft", "laufen"], ["lief", "liefst", "lief", "liefen", "lieft", "liefen"], "ist gelaufen", "Können Sie ein paar Schritte laufen?", "Can you walk a few steps?"], ["schlafen", "to sleep", ["schlafe", "schläfst", "schläft", "schlafen", "schlaft", "schlafen"], ["schlief", "schliefst", "schlief", "schliefen", "schlieft", "schliefen"], "hat geschlafen", "Wie haben Sie heute Nacht geschlafen?", "How did you sleep last night?"], ["tun", "to do", ["tue", "tust", "tut", "tun", "tut", "tun"], ["tat", "tatest", "tat", "taten", "tatet", "taten"], "hat getan", "Wo tut es weh?", "Where does it hurt?"], ["verstehen", "to understand", ["verstehe", "verstehst", "versteht", "verstehen", "versteht", "verstehen"], ["verstand", "verstandest", "verstand", "verstanden", "verstandet", "verstanden"], "hat verstanden", "Haben Sie alles verstanden?", "Did you understand everything?"], ["verschreiben", "to prescribe", ["verschreibe", "verschreibst", "verschreibt", "verschreiben", "verschreibt", "verschreiben"], ["verschrieb", "verschriebst", "verschrieb", "verschrieben", "verschriebt", "verschrieben"], "hat verschrieben", "Ich verschreibe Ihnen ein Antibiotikum.", "I'll prescribe you an antibiotic."], ["behandeln", "to treat", ["behandle", "behandelst", "behandelt", "behandeln", "behandelt", "behandeln"], ["behandelte", "behandeltest", "behandelte", "behandelten", "behandeltet", "behandelten"], "hat behandelt", "Wir behandeln die Pneumonie mit Antibiotika.", "We are treating the pneumonia with antibiotics."], ["erinnern", "to remind; sich erinnern = to remember", ["erinnere", "erinnerst", "erinnert", "erinnern", "erinnert", "erinnern"], ["erinnerte", "erinnertest", "erinnerte", "erinnerten", "erinnertet", "erinnerten"], "hat erinnert", "Erinnern Sie sich an den Sturz?", "Do you remember the fall?"], ["operieren", "to operate", ["operiere", "operierst", "operiert", "operieren", "operiert", "operieren"], ["operierte", "operiertest", "operierte", "operierten", "operiertet", "operierten"], "hat operiert", "Die Chirurgen operieren heute Nacht noch.", "The surgeons are operating tonight."], ["atmen", "to breathe", ["atme", "atmest", "atmet", "atmen", "atmet", "atmen"], ["atmete", "atmetest", "atmete", "atmeten", "atmetet", "atmeten"], "hat geatmet", "Bitte tief ein- und ausatmen.", "Please breathe in and out deeply."], ["reden", "to talk", ["rede", "redest", "redet", "reden", "redet", "reden"], ["redete", "redetest", "redete", "redeten", "redetet", "redeten"], "hat geredet", "Wir reden morgen mit Ihrer Familie.", "We'll talk to your family tomorrow."], ["sammeln", "to collect", ["sammle", "sammelst", "sammelt", "sammeln", "sammelt", "sammeln"], ["sammelte", "sammeltest", "sammelte", "sammelten", "sammeltet", "sammelten"], "hat gesammelt", "Bitte sammeln Sie 24 Stunden lang Ihren Urin.", "Please collect your urine for 24 hours."], ["wandern", "to hike", ["wandere", "wanderst", "wandert", "wandern", "wandert", "wandern"], ["wanderte", "wandertest", "wanderte", "wanderten", "wandertet", "wanderten"], "ist gewandert", "Am Wochenende sind wir im Odenwald gewandert.", "At the weekend we hiked in the Odenwald."], ["ändern", "to change", ["ändere", "änderst", "ändert", "ändern", "ändert", "ändern"], ["änderte", "ändertest", "änderte", "änderten", "ändertet", "änderten"], "hat geändert", "Wir ändern die Dosis.", "We're changing the dose."], ["anrufen", "to call (on the phone)", ["anrufe", "anrufst", "anruft", "anrufen", "anruft", "anrufen"], ["anrief", "anriefst", "anrief", "anriefen", "anrieft", "anriefen"], "hat angerufen", "Ich rufe den Oberarzt an.", "I'm calling the senior physician."], ["zurückrufen", "to call back", ["zurückrufe", "zurückrufst", "zurückruft", "zurückrufen", "zurückruft", "zurückrufen"], ["zurückrief", "zurückriefst", "zurückrief", "zurückriefen", "zurückrieft", "zurückriefen"], "hat zurückgerufen", "Die Radiologie ruft in zehn Minuten zurück.", "Radiology will call back in ten minutes."], ["aufstehen", "to get up, to stand up", ["aufstehe", "aufstehst", "aufsteht", "aufstehen", "aufsteht", "aufstehen"], ["aufstand", "aufstandest", "aufstand", "aufstanden", "aufstandet", "aufstanden"], "ist aufgestanden", "Sie dürfen heute zum ersten Mal aufstehen.", "You may get up for the first time today."], ["einnehmen", "to take (medication)", ["einnehme", "einnimmst", "einnimmt", "einnehmen", "einnehmt", "einnehmen"], ["einnahm", "einnahmst", "einnahm", "einnahmen", "einnahmt", "einnahmen"], "hat eingenommen", "Nehmen Sie die Tabletten regelmäßig ein?", "Do you take the tablets regularly?"], ["abhören", "to auscultate, to listen to (chest)", ["abhöre", "abhörst", "abhört", "abhören", "abhört", "abhören"], ["abhörte", "abhörtest", "abhörte", "abhörten", "abhörtet", "abhörten"], "hat abgehört", "Ich höre jetzt Ihre Lunge ab.", "I'm going to listen to your lungs now."], ["vorstellen", "to present; sich vorstellen = to introduce oneself / to present (at hospital)", ["vorstelle", "vorstellst", "vorstellt", "vorstellen", "vorstellt", "vorstellen"], ["vorstellte", "vorstelltest", "vorstellte", "vorstellten", "vorstelltet", "vorstellten"], "hat vorgestellt", "Ich stelle Ihnen Herrn Demir vor.", "Let me present Mr Demir to you."], ["einladen", "to invite", ["einlade", "einlädst", "einlädt", "einladen", "einladet", "einladen"], ["einlud", "einludst", "einlud", "einluden", "einludet", "einluden"], "hat eingeladen", "Wir laden die Angehörigen zum Gespräch ein.", "We're inviting the relatives for a talk."], ["anfangen", "to begin, to start", ["anfange", "anfängst", "anfängt", "anfangen", "anfangt", "anfangen"], ["anfing", "anfingst", "anfing", "anfingen", "anfingt", "anfingen"], "hat angefangen", "Wann haben die Schmerzen angefangen?", "When did the pain start?"], ["aufmachen", "to open", ["aufmache", "aufmachst", "aufmacht", "aufmachen", "aufmacht", "aufmachen"], ["aufmachte", "aufmachtest", "aufmachte", "aufmachten", "aufmachtet", "aufmachten"], "hat aufgemacht", "Machen Sie bitte den Mund auf.", "Please open your mouth."], ["aufnehmen", "to admit (a patient), to take in", ["aufnehme", "aufnimmst", "aufnimmt", "aufnehmen", "aufnehmt", "aufnehmen"], ["aufnahm", "aufnahmst", "aufnahm", "aufnahmen", "aufnahmt", "aufnahmen"], "hat aufgenommen", "Wir nehmen Sie stationär auf.", "We're admitting you to the ward."], ["abnehmen", "to take (blood); to lose weight", ["abnehme", "abnimmst", "abnimmt", "abnehmen", "abnehmt", "abnehmen"], ["abnahm", "abnahmst", "abnahm", "abnahmen", "abnahmt", "abnahmen"], "hat abgenommen", "Ich nehme Ihnen jetzt Blut ab.", "I'm going to take some blood now."], ["einweisen", "to refer/admit to hospital", ["einweise", "einweist", "einweist", "einweisen", "einweist", "einweisen"], ["einwies", "einwiesest", "einwies", "einwiesen", "einwiest", "einwiesen"], "hat eingewiesen", "Der Hausarzt hat ihn eingewiesen.", "The GP referred him to hospital."], ["entlassen", "to discharge", ["entlasse", "entlässt", "entlässt", "entlassen", "entlasst", "entlassen"], ["entließ", "entließest", "entließ", "entließen", "entließt", "entließen"], "hat entlassen", "Wir entlassen Sie morgen nach Hause.", "We'll discharge you home tomorrow."], ["bekommen", "to get, to receive", ["bekomme", "bekommst", "bekommt", "bekommen", "bekommt", "bekommen"], ["bekam", "bekamst", "bekam", "bekamen", "bekamt", "bekamen"], "hat bekommen", "Sie bekommen jetzt eine Infusion.", "You're getting a drip now."], ["erbrechen", "to vomit", ["erbreche", "erbrichst", "erbricht", "erbrechen", "erbrecht", "erbrechen"], ["erbrach", "erbrachst", "erbrach", "erbrachen", "erbracht", "erbrachen"], "hat erbrochen", "Haben Sie heute erbrochen?", "Have you vomited today?"], ["sich übergeben", "to vomit, to be sick", ["übergebe mich", "übergibst dich", "übergibt sich", "übergeben uns", "übergebt euch", "übergeben sich"], ["übergab mich", "übergabst dich", "übergab sich", "übergaben uns", "übergabt euch", "übergaben sich"], "hat sich übergeben", "Haben Sie sich übergeben?", "Have you been sick?"]];
const KONJ=()=>CONJ.concat(CONJ_EXTRA.filter(x=>!CONJ.some(c=>c[0]===x[0])));
const SEP_PRE=["zurück","weiter","zusammen","fest","los","weg","her","hin","vor","nach","mit","ein","aus","auf","bei","an","ab","zu"];
const INSEP=/^(be|ge|er|ver|zer|ent|emp|miss|hinter|wider)/;
function sepOf(inf){for(const p of SEP_PRE){if(inf.startsWith(p)&&inf.length>p.length+3){const rest=inf.slice(p.length);if(KONJ().some(c=>c[0]===rest)||CONJ_EXTRA.some(c=>c[0]===inf))return p}}return ""}
