function timeWords(h,m){if(!(h>=0&&h<=24&&m>=0&&m<=59)||(h===24&&m))return null;const hh=x=>x===1?"ein":numWord(x);const h12=h%12||12,nh=(h+1)%12||12;const c=x=>x===1?"eins":numWord(x);
  const off=h===24?"vierundzwanzig Uhr":h===0&&m===0?"null Uhr":`${hh(h)} Uhr${m?" "+numWord(m):""}`;const f=[["offiziell",off]];let col;
  if(m===0)col=h===0||h===24?"Mitternacht / zwölf Uhr nachts":h===12?"zwölf Uhr / Mittag":`${hh(h12)} Uhr / ${c(h12)}`;else if(m===15)col=`Viertel nach ${c(h12)}`;else if(m===30)col=`halb ${c(nh)}`;else if(m===45)col=`Viertel vor ${c(nh)}`;
  else if(m<=20)col=`${m===1?"eine Minute":numWord(m)} nach ${c(h12)}`;else if(m<30)col=`${numWord(30-m)} vor halb ${c(nh)}`;else if(m<40)col=`${numWord(m-30)} nach halb ${c(nh)}`;else col=`${m===59?"eine Minute":numWord(60-m)} vor ${c(nh)}`;
  f.push(["umgangssprachlich",col]);if(m===15)f.push(["süddeutsch",`viertel ${c(nh)}`]);if(m===45)f.push(["süddeutsch",`drei viertel ${c(nh)}`]);return f}
const MONATE=["Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"];const ORD=n=>n<20?({1:"erste",3:"dritte",7:"siebte",8:"achte"}[n]||Z1[n]+"te"):numWord(n)+"ste";
const ZL_UNITS={mg:["Milligramm"],g:["Gramm"],"µg":["Mikrogramm"],mcg:["Mikrogramm"],ug:["Mikrogramm"],ng:["Nanogramm"],ml:["Milliliter",0,"m"],l:["Liter",0,"m"],dl:["Deziliter",0,"m"],mmol:["Millimol"],mol:["Mol"],mval:["Milliäquivalent"],ie:["Internationale Einheit","Internationale Einheiten","f"],"i.e.":["Internationale Einheit","Internationale Einheiten","f"],e:["Einheit","Einheiten","f"],"%":["Prozent"],tbl:["Tablette","Tabletten","f"],tabl:["Tablette","Tabletten","f"],kps:["Kapsel","Kapseln","f"],amp:["Ampulle","Ampullen","f"],hub:["Hub","Hübe","m"],hübe:["Hub","Hübe","m"],tr:["Tropfen","Tropfen","m"],gtt:["Tropfen","Tropfen","m"],kg:["Kilogramm"],mmhg:["Millimeter Quecksilbersäule"],"l/min":["Liter pro Minute",0,"m"]};
const ZL_PER={kg:"pro Kilogramm Körpergewicht",h:"pro Stunde",std:"pro Stunde",min:"pro Minute",d:"pro Tag",tag:"pro Tag",die:"pro Tag",woche:"pro Woche","kg/h":"pro Kilogramm und Stunde","kg/min":"pro Kilogramm und Minute","kg/d":"pro Kilogramm und Tag",m2:"pro Quadratmeter Körperoberfläche","m²":"pro Quadratmeter Körperoberfläche"};
function doseWords(v){const m=String(v).trim().match(/^([\d.,]+)\s*([a-zA-Zµ%.]+?)\s*(?:\/\s*([a-zA-Z²0-9/]+))?$/);if(!m)return null;const p=parseDe(m[1]);if(!p)return null;const U=ZL_UNITS[m[2].toLowerCase()];if(!U)return {err:"Einheit „"+m[2]+"“ kenne ich nicht – bitte als mg, g, µg, ml, l, IE, mmol, Tbl., Amp. angeben."};
  const per=m[3]?ZL_PER[m[3].toLowerCase()]:"";if(m[3]&&!per)return {err:"„/"+m[3]+"“ kenne ich nicht – z. B. /kg, /h, /kg/h, /d, /min."};const one=p.int===1&&!p.dec;const fem=U[2]==="f";
  const n=p.dec?decWord(p):numAttr(p.int,fem);const unit=one?U[0]:(U[1]||U[0]);return {txt:n+" "+unit+(per?" "+per:""),alt:p.dec&&p.dec.length===2&&p.int===0?"null Komma "+numWord(+p.dec)+" "+unit+(per?" "+per:""):"",hint:p.hint}}
function labZahl(box){box.innerHTML=`<div class="stack s"><div class="seg zl-seg"><button class="on" data-m="num">Zahl</button><button data-m="time">Uhrzeit</button><button data-m="date">Datum</button><button data-m="price">Preis</button><button data-m="rr">Blutdruck</button><button data-m="dose">Dosis</button></div><input class="zl-in" placeholder="z. B. 147" autocomplete="off"><div class="zl-out card"></div></div>`;
  let mode="num";const inp=$(".zl-in",box),out=$(".zl-out",box);const ph={num:"z. B. 147 · 1.000 · 37,8 · 1998",time:"z. B. 14:25 oder 0:30",date:"z. B. 05.11.2026",price:"z. B. 3,50 oder 0,99",rr:"z. B. 135/85",dose:"z. B. 2,5 mg/kg · 0,25 mg · 1 IE · 500 ml/h"};
  const bad=t=>[["⚠",t]];
  const lines=()=>{const v=inp.value.trim();if(!v)return [];try{
    if(mode==="num"){const p=parseDe(v);if(!p)return bad("Keine Zahl. Tausender mit Punkt (1.000), Dezimalstellen mit Komma (37,8).");const L=[[p.txt,decWord(p)]];if(!p.dec&&numSpoken(p.int)!==numWord(p.int))L.push(["gesprochen auch",numSpoken(p.int)]);if(!p.dec&&p.int>=1100&&p.int<=2099)L.push(["als Jahreszahl",yearWord(p.int)]);if(p.dec&&p.dec.length===2&&p.int===0)L.push(["auch",`null Komma ${numWord(+p.dec)}`]);if(p.hint)L.push(["Hinweis",p.hint]);return L}
    if(mode==="time"){const mm=v.match(/^(\d{1,2})[:.]?(\d{2})?$/);if(!mm)return bad("Uhrzeit als 14:25 eingeben.");const T=timeWords(+mm[1],+(mm[2]||0));return T?T.map(([a,b])=>[a,b]):bad("Diese Uhrzeit gibt es nicht (0:00–23:59).")}
    if(mode==="date"){const mm=v.match(/^(\d{1,2})[./](\d{1,2})[./]?(\d{2,4})?$/);if(!mm)return bad("Datum als 05.11.2026 eingeben.");const d=+mm[1],mo=+mm[2];let y=mm[3]?+mm[3]:0;if(y&&y<100)y+=2000;const dim=new Date(y||2024,mo,0).getDate();if(mo<1||mo>12||d<1||d>dim)return bad("Dieses Datum gibt es nicht.");
      const tail=`${MONATE[mo-1]}${y?" "+yearWord(y):""}`;return [[v,`der ${ORD(d)} ${tail}`],["am …",`am ${ORD(d)}n ${tail}`],["kurz",`der ${ORD(d)} ${ORD(mo)}${y?" "+yearWord(y):""}`]]}
    if(mode==="price"){const p=parseDe(v.replace(/€|eur(o)?/i,"").trim());if(!p)return bad("Preis als 3,50 eingeben.");const ct=p.dec?Math.round(+("0."+p.dec)*100):0;const e=p.int;
      if(!e&&ct)return [[v+" €",`${numWord(ct)} Cent`]];const eur=`${numAttr(e,false)} Euro`;return [[v+" €",eur+(ct?" "+numWord(ct):"")],...(ct?[["ausführlich",`${eur} und ${numWord(ct)} Cent`]]:[])]}
    if(mode==="rr"){const mm=v.match(/^(\d{2,3})\s*\/\s*(\d{2,3})$/);if(!mm)return bad("Blutdruck als 135/85 eingeben.");const sy=+mm[1],di=+mm[2];if(sy<=di)return bad("Der systolische Wert (oben) muss größer sein als der diastolische.");if(sy>300||di<20)return bad("Wert außerhalb des Messbereichs – bitte prüfen.");
      return [[v+" mmHg",`${numSpoken(sy)} zu ${numSpoken(di)}`],["zum Patienten",`Ihr Blutdruck ist ${numSpoken(sy)} zu ${numSpoken(di)}.`]]}
    if(mode==="dose"){const D=doseWords(v);if(!D)return bad("Dosis als 2,5 mg oder 2,5 mg/kg eingeben.");if(D.err)return bad(D.err);const L=[[v,D.txt]];if(D.alt)L.push(["auch",D.alt]);if(D.hint)L.push(["Hinweis",D.hint]);return L}
  }catch(e){return bad("Das konnte ich nicht lesen.")}return []};
  const paint=()=>{const L=lines();out.innerHTML=L.length?L.map(([a,b])=>a==="⚠"?`<p class="ui" style="color:var(--bad)">${esc(b)}</p>`:`<div class="row between zl-row"><span><small class="muted ui">${esc(a)}</small><br><b>${esc(b)}</b></span><button class="icon ghost" data-say="${esc(b.split(" / ")[0])}">${ic("vol")}</button></div>`).join("")+(typeof xpBtn==="function"?`<div style="margin-top:.5rem">${xpBtn("zahlen")}</div>`:""):`<p class="muted ui">Tippe etwas ein. ${esc(ph[mode])}</p>`};
  $$(".zl-seg button",box).forEach(b=>b.onclick=()=>{mode=b.dataset.m;$$(".zl-seg button",box).forEach(x=>x.classList.toggle("on",x===b));inp.placeholder=ph[mode];inp.value="";paint();inp.focus()});inp.oninput=paint;inp.placeholder=ph.num;paint();setTimeout(()=>inp.focus(),50)}
// ---- Arztbrief-Werkstatt
function labBrief(box){const F=[["vor","Nebendiagnosen / Vorerkrankungen","COPD GOLD 3, Diabetes mellitus Typ 2"],["grund","Beschwerden bei Aufnahme (Stichpunkte)","seit 2 Tagen zunehmende Luftnot, produktiver Husten, Fieber bis 39 °C"],["bef","Aufnahmebefund","reduzierter AZ, feuchte RG rechts basal, SpO₂ 89 % unter Raumluft, Temp. 38,4 °C"],["diag","Diagnostik","Röntgen-Thorax: Infiltrat rechts basal; CRP 120 mg/l, Leukozyten 15/nl"],["dx","Hauptdiagnose","Ambulant erworbene Pneumonie rechts basal"],["ther","Therapie","Ampicillin/Sulbactam 3 g i.v. 1-1-1, Sauerstoff 2 l/min"],["verlauf","Verlauf (Nominalstil)","Entfieberung am 2. Tag, Rückgang des CRP auf 35 mg/l, SpO₂ 95 % unter Raumluft"],["proc","Procedere / Empfehlung","Fortführung der Antibiose p.o. für 5 Tage; Kontrolle von Klinik und CRP beim Hausarzt in 1 Woche"],["med","Medikation bei Entlassung","Amoxicillin/Clavulansäure 875/125 mg 1-0-1, Tiotropium 18 µg 1-0-0, Metformin 1000 mg 1-0-1"]];
  const iso=d=>{const x=new Date();x.setDate(x.getDate()+d);return x.toISOString().slice(0,10)};
  box.innerHTML=`<div class="stack s"><p class="muted ui" style="font-size:.9rem">So ist ein echter Entlassungsbrief gebaut: Anrede, Diagnosen, Anamnese, Befund, Diagnostik, Therapie und Verlauf, Procedere, Medikation, Gruß. Schreib die Felder im <b>Nominalstil</b> (z. B. „Entfieberung am 2. Tag“) – sie werden unverändert übernommen, der Rahmen passt sich an Frau/Herr an.</p>
   <div class="sb-fields"><label class="sb-f"><span>Patient/in</span><select class="ab-in" data-k="sex"><option value="m">Herr</option><option value="f">Frau</option></select></label><label class="sb-f"><span>Nachname</span><input class="ab-in" data-k="name" placeholder="Demir"></label><label class="sb-f"><span>Geburtsdatum</span><input class="ab-in" data-k="geb" type="date"></label><label class="sb-f"><span>Anrede an</span><select class="ab-in" data-k="an"><option value="f">Frau Kollegin</option><option value="m">Herr Kollege</option><option value="x">Kolleginnen und Kollegen</option></select></label><label class="sb-f"><span>Aufnahme</span><input class="ab-in" data-k="auf" type="date"></label><label class="sb-f"><span>Entlassung</span><input class="ab-in" data-k="ent" type="date"></label></div>
   <div class="list">${F.map(f=>`<label class="f"><span>${f[1]}</span><textarea class="ab-in" rows="2" data-k="${f[0]}" placeholder="${esc(f[2])}"></textarea></label>`).join("")}</div><div class="row wrap"><button class="sm ab-demo">Beispiel einsetzen</button><button class="sm ab-clear">Leeren</button></div><div class="card ab-out"></div><div class="row wrap"><button class="sm ab-say">${ic("vol")} Vorlesen</button><button class="sm ab-copy">${ic("pen")} Kopieren</button><button class="sm ab-check">Selbst schreiben &amp; vergleichen</button>${typeof xpBtn==="function"?xpBtn("doku")+xpBtn("passiv"):""}</div><div class="ab-fb"></div></div>`;
  const v=k=>{const el=$(`.ab-in[data-k=${k}]`,box);return (el&&el.value||"").trim().replace(/[.;\s]+$/,"")};const de=x=>{if(!x)return "…";const [y,m,d]=x.split("-");return d+"."+m+"."+y};
  const gen=()=>{const f=v("sex")==="f",N=v("name")||"…",who=f?"Frau "+N:"Herrn "+N,whoN=f?"Frau "+N:"Herr "+N,rel=f?"die":"der",pat=f?"Ihre Patientin":"Ihren Patienten";const L=[];
    L.push(v("an")==="f"?"Sehr geehrte Frau Kollegin,":v("an")==="m"?"Sehr geehrter Herr Kollege,":"Sehr geehrte Kolleginnen und Kollegen,");
    L.push(`wir berichten über ${pat}, ${who}, geb. am ${de(v("geb"))}, ${rel} sich vom ${de(v("auf"))} bis zum ${de(v("ent"))} in unserer stationären Behandlung befand.`);
    if(v("dx")||v("vor"))L.push("<b>Diagnosen:</b>"+(v("dx")?"<br>"+esc(v("dx")):"")+(v("vor")?"<br><b>Nebendiagnosen:</b><br>"+v("vor").split(/\s*[,;\n]\s*/).map(esc).join("<br>"):""));
    if(v("grund"))L.push(`<b>Anamnese:</b> Die Vorstellung erfolgte mit folgenden Beschwerden: ${esc(v("grund"))}.`);
    if(v("bef"))L.push(`<b>Aufnahmebefund:</b> ${esc(v("bef"))}.`);
    if(v("diag"))L.push(`<b>Diagnostik:</b> ${esc(v("diag"))}.`);
    if(v("ther")||v("verlauf"))L.push(`<b>Therapie und Verlauf:</b> ${v("ther")?`Es wurde folgende Therapie eingeleitet: ${esc(v("ther"))}. `:""}${v("verlauf")?`Im weiteren Verlauf zeigte sich: ${esc(v("verlauf"))}. `:""}Wir entlassen ${who} am ${de(v("ent"))} in gebessertem Allgemeinzustand nach Hause.`);
    if(v("proc"))L.push(`<b>Procedere:</b> ${esc(v("proc"))}. Bei Verschlechterung bitten wir um umgehende Wiedervorstellung.`);
    if(v("med"))L.push("<b>Medikation bei Entlassung:</b><br>"+v("med").split(/\s*[;\n]\s*|,\s+(?=[A-ZÄÖÜ])/).map(esc).join("<br>"));
    L.push("Für Rückfragen stehen wir Ihnen gern zur Verfügung.");L.push("Mit freundlichen kollegialen Grüßen<br>Dr. Amron Ismail<br>Assistenzarzt");return L};
  const plain=()=>gen().join("\n\n").replace(/<br>/g,"\n").replace(/<[^>]+>/g,"").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&#39;/g,"'");
  const paint=()=>{const any=$$(".ab-in",box).some(i=>i.tagName==="TEXTAREA"&&i.value.trim()||i.dataset.k==="name"&&i.value.trim());$(".ab-out",box).innerHTML=any?`<div class="eyebrow">Entlassungsbrief <span class="en">your notes, framed</span></div><div class="ab-letter">${gen().map(x=>`<p>${x}</p>`).join("")}</div>`:'<p class="muted ui">Der Brief erscheint hier, sobald du etwas einträgst.</p>'};
  $$(".ab-in",box).forEach(i=>i.oninput=i.onchange=paint);
  $(".ab-demo",box).onclick=()=>{F.forEach(f=>$(`.ab-in[data-k=${f[0]}]`,box).value=f[2]);const set=(k,x)=>$(`.ab-in[data-k=${k}]`,box).value=x;set("sex","m");set("name","Demir");set("geb","1959-03-14");set("an","f");set("auf",iso(-6));set("ent",iso(0));paint()};
  $(".ab-clear",box).onclick=()=>{$$(".ab-in",box).forEach(i=>{if(i.tagName!=="SELECT")i.value=""});paint()};
  $(".ab-say",box).onclick=()=>say(plain());$(".ab-copy",box).onclick=()=>copyText(plain());
  $(".ab-check",box).onclick=()=>{if(!v("dx")&&!v("grund"))return toast("Erst Stichpunkte eintragen (oder Beispiel einsetzen)");const fbx=$(".ab-fb",box);fbx.innerHTML="";freeText(fbx,{t:"Arztbrief",task:"Schreib den Abschnitt „Therapie und Verlauf“ und das Procedere selbst – in ganzen Sätzen, Präteritum/Passiv, Nominalstil. Danach vergleichst du mit dem Rahmen oben.",ctx:"Arztbrief-Werkstatt",reg:"Arztbrief: Nominalstil, Präteritum, Passiv, Fachsprache",check:["Therapie mit Dosis und Applikationsweg","Verlauf mit konkretem Ergebnis","Entlassung (Datum, Zustand)","Procedere / Empfehlung"],model:plain()},{});fbx.scrollIntoView({behavior:"smooth"})};paint()}
