// ---- 13. offline FSP: a patient who answers only what you ask, notes → Teil 2, the case's own Oberarzt questions,
//          Fachbegriffe, diagnosis hidden until the end, a stored rubric score
fspModel=function(c){const w=c.sex==="w"||/^Frau/.test(c.name);return `Anamnese: ${c.age}-jährige${w?" Patientin":"r Patient"}, ${c.job}. Vorstellung wegen: ${c.cc}.\nVorerkrankungen: ${c.pmh}.\nMedikation: ${c.meds}.\nAllergien: ${c.all}.\nSozial- und Noxenanamnese: ${c.soc}.\nFamilienanamnese: ${c.fam||"unauffällig"}.\nVerdachtsdiagnose / DD: ${c.dx}.\nProcedere: ${c.plan}.`};
const FSP_RUB=[["fam","Familienanamnese",/familie|eltern|vater|mutter|geschwister|erblich|verwandt/i],["hpi","Leitsymptom, Beginn, Verlauf",/seit wann|wann (hat|haben|ist)|wie (hat|ist) es|was führt|beschwerden|schmerz|erzählen|wo genau|wie stark|skala|ausstrahl|verlauf|plötzlich|begleit|übel|erbroch|fieber|husten|luftnot|atemnot|schwindel|was ist passiert|wie fühlen/i],
 ["pmh","Vorerkrankungen, Operationen",/vorerkrank|krankheit|erkrank|operiert|operation|krankenhaus|chronisch|diabetes|blutdruck|herz/i],["meds","Medikation",/medikament|tablette|nehmen sie|einnehm|pille|spray|insulin|blutverdünn/i],
 ["all","Allergien",/allergi|vertragen|unverträglich/i],["nox","Noxen",/rauch|zigarett|alkohol|trinken sie|drogen|nikotin/i],["soc","Sozialanamnese",/beruf|arbeit|wohnen|leben sie|verheiratet|kinder|allein|versorgt|pflege/i],
["veg","Vegetative Anamnese",/schlaf|appetit|gewicht|stuhl|wasserlassen|urin|nachtschweiß|durst/i],["gyn","Gynäkologische Anamnese",/periode|regel|schwanger|menstruation|verhütung/i]];
function fspPatient(c){const w=c.sex==="w"||/^Frau/.test(c.name);const hpi=String(c.hpi||("Also, "+c.cc+".")).split(/(?<=[.!?])\s+/);let hi=0;const soc=String(c.soc||"");
  const noxS=soc.split(/[,;]\s*/).filter(x=>/rauch|alkohol|drogen|nikotin|py|pack/i.test(x)).join(", ");const socS=soc.split(/[,;]\s*/).filter(x=>!/rauch|alkohol|drogen|nikotin|py|pack/i.test(x)).join(", ");
  return {ask(q){const t=String(q);if(/\b(du|dich|dir|dein\w*)\b/i.test(t))return {k:"",a:"(irritiert) Entschuldigung … kennen wir uns? Ich bin es gewohnt, dass man mich siezt."};
    const R=FSP_RUB.filter(r=>r[2].test(t));if(!R.length)return {k:"",a:"Wie meinen Sie das? Können Sie die Frage anders stellen?"};const k=R[0][0];
    if(k==="hpi"){const a=hpi.slice(hi,hi+2).join(" ")||"Mehr kann ich dazu eigentlich nicht sagen.";hi+=2;return {k,a}}
    const A={pmh:"Vorerkrankungen … "+c.pmh+".",meds:"Ich nehme: "+c.meds+".",all:"Allergien: "+c.all+".",nox:noxS?noxS[0].toUpperCase()+noxS.slice(1)+".":"Ich rauche nicht, Alkohol nur selten.",soc:socS?socS[0].toUpperCase()+socS.slice(1)+".":"Dazu gibt es nicht viel zu sagen.",fam:c.fam?"In der Familie: "+c.fam+".":"In der Familie ist nichts Besonderes bekannt.",veg:/schlaf/i.test(t)?"Geschlafen habe ich wegen der Beschwerden schlecht.":/appetit|gewicht/i.test(t)?"Appetit habe ich gerade wenig, abgenommen habe ich nicht.":"Das ist eigentlich normal.",gyn:w?"Meine letzte Periode war vor etwa drei Wochen, eigentlich regelmäßig. Schwanger bin ich nicht, soweit ich weiß.":"(lacht) Das betrifft mich wohl nicht."};return {k,a:A[k]}}}}
function fspOffline(el,o){o=o||{};const pool=FSP_CASES.filter(x=>x.hpi);const c=(pool.length?pool:FSP_CASES)[Math.floor(Math.random()*(pool.length||FSP_CASES.length))];const w=c.sex==="w"||/^Frau/.test(c.name);
  let part=0,left=1200,tm=null,notes="",doc="",covered=new Set(),asked=[],ansO=[],ansT=[],terms=[],pq=null;const P=fspPatient(c);const res={};const T=["Teil 1 · Arzt-Patienten-Gespräch","Teil 2 · Dokumentation","Teil 3 · Arzt-Arzt-Gespräch"];
  const timer=()=>{clearInterval(tm);left=1200;Focus.tools(`<span class="chip fsp-t">${ic("timer")} 20:00</span>`);tm=every(()=>{left=Math.max(0,left-1);const x=$(".fsp-t");if(x)x.innerHTML=ic("timer")+" "+pad(Math.floor(left/60))+":"+pad(left%60);if(!left){clearInterval(tm);toast("20 Minuten um");const n=$(".fsp-n",el);if(n)n.classList.add("pulse")}},1000)};
  const next=()=>{part++;draw()};
  function p1(){const need=FSP_RUB.filter(r=>r[0]!=="gyn"||w);el.innerHTML=`<div class="card k stack s"><div class="eyebrow">${T[0]}</div><p><b>${esc(c.name)}</b>, ${c.age} Jahre, kommt in die Notaufnahme. Mehr weißt du nicht – frag nach (Sie-Form, Laiensprache).</p></div>
    <div class="card dl fsp-chat"></div><div class="typed"><input class="fsp-q" placeholder="Ihre Frage an ${w?"die Patientin":"den Patienten"} …" autocomplete="off"><button class="primary fsp-ask">Fragen</button></div>
    <details class="card" open><summary class="ui">Notizen (nur diese hast du in Teil 2)</summary><textarea class="fsp-notes" rows="6" placeholder="Stichpunkte …"></textarea></details>
    <div class="row between"><span class="muted ui fsp-cov" style="font-size:.85rem"></span><button class="primary fsp-n">Gespräch beenden → Teil 2</button></div>`;
    const chat=$(".fsp-chat",el),q=$(".fsp-q",el),cov=$(".fsp-cov",el),nt=$(".fsp-notes",el);nt.value=notes;nt.oninput=()=>notes=nt.value;
    const paintCov=()=>cov.textContent=`${[...covered].filter(k=>need.some(r=>r[0]===k)).length} von ${need.length} Rubriken angesprochen`;paintCov();
    const say1=(who,txt,cls)=>{chat.insertAdjacentHTML("beforeend",`<div class="turn ${cls||""}"><div class="who"><span>${who}</span>${who!=="Du"?`<button data-say="${esc(txt)}">${ic("vol")}</button>`:""}</div><div data-gk="${glossKey({})}">${glossify(txt)}</div></div>`);chat.scrollTop=chat.scrollHeight};
    say1(w?"Patientin":"Patient",w?"Guten Tag, Frau Doktor … oder Herr Doktor? Mir geht es gar nicht gut.":"Guten Tag, Herr Doktor. Mir geht es gar nicht gut.");
    const ask=()=>{const t=q.value.trim();if(!t)return;q.value="";asked.push(t);say1("Du",t,"me");const r=P.ask(t);if(r.k)covered.add(r.k);setTimeout(()=>{say1(w?"Patientin":"Patient",r.a);say(r.a,{silent:true});
      if(asked.length>=6&&c.patientQs&&c.patientQs.length&&!pq){const ctx=chat.textContent.toLowerCase();const st=x=>x.toLowerCase().replace(/[^a-zäöüß ]/g," ").split(/\s+/).filter(y=>y.length>=5).map(y=>y.slice(0,5));
        const best=c.patientQs.map(x=>[x,st(x).filter(k=>ctx.includes(k)).length]).sort((a,b)=>b[1]-a[1])[0];if(best&&(best[1]>0||asked.length>=10)){pq=best[0];setTimeout(()=>{say1(w?"Patientin":"Patient",pq);toast("Die Patientin/der Patient fragt dich – antworte in Laiensprache.")},600)}}paintCov()},250)};
    $(".fsp-ask",el).onclick=ask;q.onkeydown=e=>{if(e.key==="Enter")ask()};setTimeout(()=>q.focus(),60);
    $(".fsp-n",el).onclick=()=>{res.cov=need.map(r=>[r[1],covered.has(r[0])]);next()}}
  function p2(){let vit=(String(c.dx||"")+"; "+String(c.exam||"")).match(/(?:Atemfrequenz|AF|RR|HF|Puls|SpO2|SpO₂|Temperatur|Temp\.?|GCS|BZ)\s*[:\s]?\s*[\d][^;,)]*/g)||[];if(vit.length<3)vit=fspVitals(c);
    el.innerHTML=`<div class="card k"><div class="eyebrow">${T[1]}</div><p>Schreib den Anamnesebogen <b>nur aus deinen Notizen</b> – im Nominalstil, mit Verdachtsdiagnose, DD und Procedere.</p>${vit.length?`<div class="tch-merke"><b>Befunde der Pflege:</b> ${esc(vit.join(" · "))}</div>`:""}${notes.trim()?`<details class="card"><summary class="ui">Deine Notizen</summary><p style="white-space:pre-wrap">${esc(notes)}</p></details>`:'<p class="muted ui">Du hast keine Notizen gemacht – in der echten Prüfung ein Problem.</p>'}</div><textarea class="fsp-doc" rows="12" placeholder="Anamnese: …&#10;Vorerkrankungen: …&#10;Medikation: …&#10;Allergien: …&#10;Noxen: …&#10;Sozialanamnese: …&#10;Familienanamnese: …&#10;Verdachtsdiagnose / DD: …&#10;Procedere: …"></textarea><div class="row"><button class="primary fsp-n">Abgeben → Teil 3</button></div>`;
    const d=$(".fsp-doc",el);d.value=doc;d.oninput=()=>doc=d.value;$(".fsp-n",el).onclick=next}
  function p3(){const qs=(c.oberarztQs&&c.oberarztQs.length?c.oberarztQs:["Welche Differentialdiagnosen kommen in Betracht?","Welche Diagnostik veranlassen Sie und warum?","Wie behandeln Sie initial?"]).slice(0,3);
    terms=shuffle(TERMS.filter(t=>t[3])).slice(0,5);const items=[{q:"Stellen Sie mir "+(w?"die Patientin":"den Patienten")+" bitte vor.",k:"vor"}].concat(qs.map(x=>({q:x,k:"oa"})));let i=0;
    const step=()=>{if(i<items.length){const it=items[i];el.innerHTML=`<div class="card k"><div class="eyebrow">${T[2]} · Oberarzt ${i+1}/${items.length}</div><div class="turn"><div class="who"><span>Oberarzt</span><button data-say="${esc(it.q)}">${ic("vol")}</button></div><div data-gk="${glossKey({})}">${glossify(it.q)}</div></div></div><textarea class="fsp-a" rows="${it.k==="vor"?7:4}" placeholder="Ihre Antwort (am besten erst laut sprechen, dann aufschreiben) …"></textarea><div class="row"><button class="icon fsp-mic need-sr">${ic("mic")}</button><button class="primary fsp-go">Weiter</button></div>`;
        const ta=$(".fsp-a",el);const mic=$(".fsp-mic",el);if(mic&&typeof dictateInto==="function")mic.onclick=()=>dictateInto(mic,ta);say(it.q,{silent:true});$(".fsp-go",el).onclick=()=>{ansO.push([it.q,ta.value.trim()]);i++;step()};return}
      const j=i-items.length;if(j<terms.length){const t=terms[j];const toF=j%2===0;el.innerHTML=`<div class="card k"><div class="eyebrow">${T[2]} · Fachbegriffe ${j+1}/${terms.length}</div><p>${toF?`Wie heißt „<b>${esc(t[0])}</b>“ in der Fachsprache?`:`Erklären Sie „<b>${esc(t[1])}</b>“ für einen Patienten.`}</p></div><div class="typed"><input class="fsp-t2" autocomplete="off" autocapitalize="off"><button class="primary fsp-go">Weiter</button></div>`;
        const inp=$(".fsp-t2",el);setTimeout(()=>inp.focus(),40);const go2=()=>{const g=normT(inp.value).replace(/^(der|die|das)\s+/,"");const want=(toF?[t[1]].concat(t[4]||[]):[t[0]]).map(x=>normT(x).replace(/^(der|die|das)\s+/,""));let ok=!!g&&want.some(a=>a===g||(typeof similarity==="function"&&similarity(a,g)>=.85));
          if(!ok&&!toF&&g){const stem=w=>w.toLowerCase().replace(/[^a-zäöüß]/g,"").slice(0,5);const kw=String(t[0]).replace(/^(der|die|das)\s+/,"").split(/[\s,/()-]+/).filter(x=>x.length>=4).map(stem);const gw=g.split(/[\s,/()-]+/).filter(x=>x.length>=4).map(stem);
            const sub=String(t[0]).toLowerCase().split(/[\s-]+/).flatMap(w=>w.length>=8?[w.slice(0,5),w.slice(-5)]:[]);ok=kw.some(k=>gw.includes(k))||sub.some(k=>k.length>=5&&g.includes(k))||(typeof similarity==="function"&&want.some(a=>similarity(a,g)>=.6))}ansT.push([toF?t[0]:t[1],inp.value.trim(),toF?t[1]:t[0],ok]);i++;step()};$(".fsp-go",el).onclick=go2;inp.onkeydown=e=>{if(e.key==="Enter")go2()};return}
      next()};step()}
  function result(){clearInterval(tm);Focus.tools("");const tOk=ansT.filter(x=>x[3]).length;const covN=(res.cov||[]).filter(x=>x[1]).length,covT=(res.cov||[]).length||1;
    const sc1=Math.max(1,Math.min(5,Math.round(1+4*covN/covT)));const sc3t=Math.round(1+4*tOk/Math.max(1,ansT.length));
    el.innerHTML=`<div class="stack s"><div class="celebrate fade-in"><div class="eyebrow">FSP-Simulation · Auswertung</div><h2>${esc(c.name)}, ${c.age}</h2><p class="muted">Jetzt sehen: Diagnose, Erwartungshorizont, Fallen. Dann bewertest du dich selbst.</p></div>
     <div class="card stack s"><h3>Teil 1 · Anamnese <span class="pill ${sc1>=4?"good":"o"}">${covN}/${covT} Rubriken</span></h3><div class="list">${(res.cov||[]).map(([n,ok])=>`<div class="li" style="cursor:default"><span class="t">${ok?"✓":"✗"} ${esc(n)}</span></div>`).join("")}</div>${asked.length?`<details><summary class="ui">Deine ${asked.length} Fragen</summary><ul>${asked.map(a=>`<li>${esc(a)}</li>`).join("")}</ul></details>`:""}</div>
     <div class="card stack s"><h3>Teil 2 · Dokumentation</h3><div class="grid2"><div><div class="eyebrow">Deine Version</div><p style="white-space:pre-wrap;font-size:.92rem">${esc(doc||"–")}</p></div><div><div class="eyebrow">Muster</div><p style="white-space:pre-wrap;font-size:.92rem">${esc(fspModel(c))}</p></div></div><div class="fsp-coach"></div></div>
     <div class="card stack s"><h3>Teil 3 · Oberarzt</h3>${ansO.map(([q,a])=>`<div><b>${esc(q)}</b><p style="white-space:pre-wrap;font-size:.92rem">${esc(a||"–")}</p></div>`).join("")}<div class="tch-merke"><b>Erwartet:</b> ${esc(c.dx)}<br><b>Procedere:</b> ${esc(c.plan)}</div>${c.traps?`<div class="tch-merke" style="border-color:var(--bad)"><b>Prüfungsfallen:</b> ${esc(c.traps)}</div>`:""}
      <div class="eyebrow">Fachbegriffe · ${tOk}/${ansT.length}</div><div class="list">${ansT.map(([q,g,a,ok])=>`<div class="li" style="cursor:default"><span class="t"><b>${ok?"✓":"✗"} ${esc(q)}</b><small>${esc(g||"–")} → ${esc(a)}</small></span></div>`).join("")}</div></div>
     <div class="card stack s"><h3>Selbstbewertung</h3><p class="muted ui" style="font-size:.9rem">Ehrlich, wie ein Prüfer: 1 = nicht bestanden · 3 = knapp · 5 = sicher.</p>
      ${[["p1","Teil 1 · Gespräch (Struktur, Laiensprache, Empathie)",sc1],["p2","Teil 2 · Dokumentation (Vollständigkeit, Nominalstil)",3],["p3","Teil 3 · Vorstellung & Fragen (Fachsprache, Begründung)",Math.round((3+sc3t)/2)]].map(([k,l,d])=>`<label class="stack" style="gap:.2rem"><span class="ui">${l}</span><input type="range" min="1" max="5" step="1" value="${d}" class="fsp-r" data-k="${k}"><small class="muted ui fsp-rv">${d} / 5</small></label>`).join("")}
      <button class="primary fsp-save">Speichern</button></div></div>`;
    $$(".fsp-r",el).forEach(r=>r.oninput=()=>r.nextElementSibling.textContent=r.value+" / 5");
    if(doc.trim()&&typeof teachRender==="function"){try{teachRender($(".fsp-coach",el),doc,{t:"FSP Teil 2",task:"Anamnesebogen",reg:"Nominalstil, Fachsprache, Abkürzungen erlaubt",model:fspModel(c),check:[]},{})}catch(e){}}
    $(".fsp-save",el).onclick=()=>{const v=$$(".fsp-r",el).map(r=>+r.value);const avg=Math.round(10*v.reduce((a,b)=>a+b,0)/v.length)/10;S.fsp=S.fsp||[];S.fsp.push({date:todayKey(),c:c.name,score:avg,parts:v,terms:tOk+"/"+ansT.length,cov:covN+"/"+covT});
      logEvent("fsp","FSP-Simulation · "+c.name+" · "+avg+"/5",Math.round(avg*20));logDay("fsp");saveSoon();toast("Gespeichert: "+avg+" / 5");if(o.onDone)o.onDone(avg)}}
  function draw(){Focus.progress({n:3,i:Math.min(part,3)});if(part>=3)return result();Focus.title("FSP-Simulation",T[part]);timer();[p1,p2,p3][part]()}
  draw()}
(function(){const _fr=fspRunner;fspRunner=function(el,o){if(SAMPLE)return _fr(el,o);return fspOffline(el,o)}})();

// ---- 14. Satzbaukasten: chips without give-away capitals, every valid word order accepted, the solution shown field by field
const SATZ2=[
 {c:["seit zwei Tagen","hat","der Patient","starke Schmerzen","."],a:"Seit zwei Tagen hat der Patient starke Schmerzen.",alt:["Der Patient hat seit zwei Tagen starke Schmerzen.","Starke Schmerzen hat der Patient seit zwei Tagen."],f:[["Seit zwei Tagen","Vorfeld"],["hat","Verb (2)"],["der Patient starke Schmerzen","Mittelfeld"]],r:"v2"},
 {c:["ich","muss","Ihnen","Blut","abnehmen","."],a:"Ich muss Ihnen Blut abnehmen.",alt:["Blut muss ich Ihnen abnehmen.","Ihnen muss ich Blut abnehmen."],f:[["Ich","Vorfeld"],["muss","Verb (2)"],["Ihnen Blut","Mittelfeld"],["abnehmen","Ende"]],r:"modal"},
 {c:["der Oberarzt","sagt",",","dass","die Werte","stabil","sind","."],a:"Der Oberarzt sagt, dass die Werte stabil sind.",alt:[],f:[["Der Oberarzt","Vorfeld"],["sagt","Verb (2)"],[", dass","Nebensatz"],["die Werte stabil","Mitte"],["sind","Verb am Ende"]],r:"vend"},
 {c:["morgen","wird","der Patient","operiert","."],a:"Morgen wird der Patient operiert.",alt:["Der Patient wird morgen operiert."],f:[["Morgen","Vorfeld"],["wird","Verb (2)"],["der Patient","Mittelfeld"],["operiert","Ende"]],r:"passiv"},
 {c:["nehmen","Sie","die Tablette","nach dem Essen","ein","."],a:"Nehmen Sie die Tablette nach dem Essen ein.",alt:["Nehmen Sie nach dem Essen die Tablette ein."],f:[["Nehmen","Verb (1) = Aufforderung"],["Sie die Tablette nach dem Essen","Mittelfeld"],["ein","Ende"]],r:"trenn"},
 {c:["wenn","das Fieber","steigt",",","rufen","Sie","uns","an","."],a:"Wenn das Fieber steigt, rufen Sie uns an.",alt:["Rufen Sie uns an, wenn das Fieber steigt."],f:[["Wenn das Fieber steigt,","Vorfeld = ganzer Nebensatz"],["rufen","Verb (2)"],["Sie uns","Mittelfeld"],["an","Ende"]],r:"vend"},
 {c:["gestern","habe","ich","den Patienten","untersucht","."],a:"Gestern habe ich den Patienten untersucht.",alt:["Ich habe gestern den Patienten untersucht.","Den Patienten habe ich gestern untersucht.","Ich habe den Patienten gestern untersucht."],f:[["Gestern","Vorfeld"],["habe","Verb (2)"],["ich den Patienten","Mittelfeld"],["untersucht","Ende"]],r:"perfekt"},
 {c:["könnten","Sie","bitte","den Mund","aufmachen","?"],a:"Könnten Sie bitte den Mund aufmachen?",alt:["Könnten Sie den Mund bitte aufmachen?"],f:[["Könnten","Verb (1) = Frage/Bitte"],["Sie bitte den Mund","Mittelfeld"],["aufmachen","Ende"]],r:"k2"}];
labSatz=function(box){let i=0;const draw=()=>{const s=SATZ2[i%SATZ2.length];const toks=shuffle(s.c.map((w,k)=>({w,k})));let line=[];
  box.innerHTML=`<div class="stack s"><div class="eyebrow">Satz ${i%SATZ2.length+1} / ${SATZ2.length} <span class="en">tap the pieces in order</span></div><div class="gr-line sb-line"></div><div class="gr-pool sb-pool"></div><div class="row wrap"><button class="sm ghost sb-undo">${ic("back")} Zurück</button><button class="primary sb-chk">Prüfen</button><button class="sm sb-next">Nächster</button></div><div class="sb-why"></div><p class="muted ui" style="font-size:.85rem">Hauptsatz: <b>ein</b> Element vor dem Verb (das Vorfeld – oft gibt es mehrere richtige Möglichkeiten), Verb an Position 2, zweiter Verbteil ans Ende. Nebensatz (dass/weil/wenn): Verb ganz ans Ende. Großbuchstaben am Satzanfang setzt die App selbst.</p></div>`;
  const L=$(".sb-line",box),P=$(".sb-pool",box);const paint=()=>{L.innerHTML=line.map(t=>`<button class="gr-tok on" data-k="${t.k}">${esc(t.w)}</button>`).join("")||'<span class="muted ui">…</span>';P.innerHTML=toks.filter(t=>!line.includes(t)).map(t=>`<button class="gr-tok" data-k="${t.k}">${esc(t.w)}</button>`).join("");$$(".gr-tok",P).forEach(b=>b.onclick=()=>{line.push(toks.find(t=>t.k===+b.dataset.k));paint()});$$(".gr-tok",L).forEach(b=>b.onclick=()=>{line=line.filter(t=>t.k!==+b.dataset.k);paint()})};paint();
  $(".sb-undo",box).onclick=()=>{line.pop();paint()};$(".sb-next",box).onclick=()=>{i++;draw()};
  $(".sb-chk",box).onclick=()=>{if(line.length<s.c.length)return toast("Erst alle Teile verwenden");let got=line.map(t=>t.w).join(" ").replace(/\s+([.,!?])/g,"$1");got=got[0].toUpperCase()+got.slice(1);
    const ok=[s.a].concat(s.alt).some(x=>normT(x)===normT(got))||(typeof v2Same==="function"&&v2Same(s.a,got));fb(ok);
    const fields=`<div class="dg-row" style="flex-wrap:wrap">${s.f.map(([t,l],k)=>`<span class="dg ${/Verb/.test(l)?"dg-verb":/Vorfeld/.test(l)?"dg-p1":/Ende/.test(l)?"dg-end":"dg-rest"}">${esc(t)}<small>${esc(l)}</small></span>`).join("")}</div>`;
    const ws=line.map(t=>t.w.toLowerCase());const fin=typeof tVForms==="function"?tVForms():new Set();const vi=ws.findIndex(w=>fin.has(w.split(" ")[0])&&!/^ge/.test(w));
    const hint=ok?"":vi===-1?"Wo ist das konjugierte Verb?":/^(wenn|weil|dass|ob)$/.test(ws[0])&&ws.indexOf(",")>-1&&ws.indexOf(",")-1!==vi?"Im Nebensatz steht das Verb direkt vor dem Komma – ganz am Ende des Nebensatzes.":vi>1&&!/^(wenn|weil|dass|ob)$/.test(ws[0])?"Vor dem Verb darf nur EIN Satzglied stehen (Position 2).":"Fast – vergleiche die Felder unten.";
    $(".sb-why",box).innerHTML=`<div class="verdict ${ok?"ok":"no"}" data-noxp="1"><b>${ok?"Richtig.":"Noch nicht."}</b> ${esc(hint)} ${ok&&normT(got)!==normT(s.a)?"Andere Stellung, auch richtig. Die Musterlösung:":"So ist der Satz gebaut:"}${fields}<div class="row" style="margin-top:.4rem"><button class="sm ghost" data-say="${esc(s.a)}">${ic("vol")}</button>${typeof xpBtn==="function"?xpBtn(s.r):""}</div></div>`;logDay("drill")}};draw()};

// ---- 15. long-run fixes: load-aware new cards, the "System" hold mode, wide lesson tables, Wort des Tages, 5-Minuten
function newAllowance(){resetNewToday();const base=Math.max(0,S.newPerDay-S.newToday.n);const due=dueKeys().length;const cap=Math.max(40,(S.minutes||60)*3);if(due>cap)return 0;if(due>cap/2)return Math.min(base,Math.ceil(S.newPerDay/3));return base}
(function(){const _np=newPool;newPool=function(tag){const keep=S.newPerDay;try{resetNewToday();S.newPerDay=S.newToday.n+newAllowance();return _np(tag)}finally{S.newPerDay=keep}}})();
(function(){const _el=xlEligible;xlEligible=function(t){return (typeof holdMode!=="function"||holdMode()!=="system")&&_el(t)}})();
// real files in the installed app (no claude.ai download capability there): share sheet on phones, download elsewhere
(function(){const _sf=saveFile;saveFile=async function(name,text){if(DOWNLOADS)return _sf(name,text);try{const type=/\.csv$/.test(name)?"text/csv":"application/json";const file=new File([text],name,{type});
  if(navigator.canShare&&navigator.canShare({files:[file]})&&/Android|iPhone|iPad/i.test(navigator.userAgent)){await navigator.share({files:[file],title:name});return true}
  const url=URL.createObjectURL(file);const a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},1500);toast("Gespeichert: "+name);return true}catch(e){if(e&&e.name==="AbortError")return false;return null}}})();

// ---- 16. no German voice on the device: say so, never burn an attempt, offer a text-based alternative
function hasDeVoice(){try{if(typeof DE_VOICE!=="undefined"&&DE_VOICE)return true;return TTS_OK&&speechSynthesis.getVoices().some(v=>/^de/i.test(v.lang))}catch(e){return false}}
(function(){let warned=false;const _say=say;say=function(t,o){if(!hasDeVoice()&&!(o&&o.silent)&&!warned){warned=true;toast("Keine deutsche Stimme auf diesem Gerät – Ton fehlt. Systemeinstellungen → Sprachausgabe → Deutsch.")}return _say(t,o)}})();
(function(){const _dr=dictationRunner;dictationRunner=function(el,lines,o){if(hasDeVoice()||!lines||!lines.length)return _dr(el,lines,o);o=o||{};let i=0,score=0;
  const draw=()=>{if(i>=lines.length){const pct=Math.round(100*score/lines.length);el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Gedächtnis-Diktat</div><h2>${pct} %</h2><button class="primary dm-ok">Weiter</button></div>`;$(".dm-ok",el).onclick=()=>{if(o.onDone)o.onDone(pct)};logDay("dict");return}
    const L=lines[i];el.innerHTML=`<div class="stack s"><div class="tch-merke"><b>Keine deutsche Stimme auf diesem Gerät.</b> Statt Hören: Lies den Satz, er verschwindet nach ein paar Sekunden – dann schreib ihn aus dem Gedächtnis.</div><div class="eyebrow">Satz ${i+1} / ${lines.length}</div><div class="card dm-s" style="font-size:1.15rem;min-height:3rem">${esc(L.de)}</div><textarea class="dm-in" rows="2" placeholder="Aus dem Gedächtnis …" disabled></textarea><div class="row"><button class="primary dm-chk" disabled>Prüfen</button><button class="sm ghost dm-again">Nochmal zeigen</button></div><div class="dm-out"></div></div>`;
    const sEl=$(".dm-s",el),inp=$(".dm-in",el),chk=$(".dm-chk",el);const hide=()=>{sEl.innerHTML='<span class="muted ui">… jetzt schreiben</span>';inp.disabled=false;chk.disabled=false;inp.focus()};let t=setTimeout(hide,Math.max(2500,L.de.length*90));
    $(".dm-again",el).onclick=()=>{clearTimeout(t);sEl.textContent=L.de;t=setTimeout(hide,2500)};
    chk.onclick=()=>{const s=typeof similarity==="function"?similarity(normT(inp.value),normT(L.de)):(normT(inp.value)===normT(L.de)?1:0);if(s>=.9)score++;$(".dm-out",el).innerHTML=`<div class="verdict ${s>=.9?"ok":"no"}" data-noxp="1">${typeof wordDiff==="function"?wordDiff(inp.value,L.de):esc(L.de)}<div class="row" style="margin-top:.5rem"><button class="primary dm-nx">Weiter</button></div></div>`;$(".dm-nx",el).onclick=()=>{i++;draw()};chk.disabled=true}};draw()}})();

