ACT.webList=()=>{if(Focus.isOpen())Focus.close(true);const box=Focus.open({title:"Grammatik-Landkarte",sub:"als Liste"});const best=id=>Math.max((S.lessons[id]||{}).best||0,((S.gram||{})[id]||{}).best||0);const T=id=>(lessonById(id)||{}).title||id;
  const pre=id=>WEB_EDGES.filter(e=>e[1]===id).map(e=>e[0]),post=id=>WEB_EDGES.filter(e=>e[0]===id).map(e=>e[1]);
  box.innerHTML=`<div class="stack s"><div class="row between"><span class="muted ui" style="font-size:.85rem">Was baut worauf auf – tippe eine Lektion zum Öffnen.</span><button class="sm" data-act="web">Als Karte</button></div>${["A1","A2","B1","B2"].map(L=>`<div class="eyebrow">${L}</div><div class="list">${GRAMMAR.filter(g=>(g.level||"B1")===L).map(g=>{const b=best(g.id);const ready=pre(g.id).every(p=>best(p)>=60);return `<button class="li" data-act="xpLesson" data-id="${g.id}"><span class="n" style="${b>=70?"background:var(--o);color:#fff":""}">${b>=70?"✓":b>0?b:"·"}</span><span class="t"><b>${esc(g.title)}</b><small>${pre(g.id).length?"braucht: "+pre(g.id).map(T).join(", "):"Einstieg"}${post(g.id).length?" · öffnet: "+post(g.id).map(T).join(", "):""}</small></span><span class="m">${b>=70?'<span class="pill good">bestanden</span>':ready?'<span class="pill o">bereit</span>':""}</span></button>`}).join("")}</div>`).join("")}</div>`};
(function(){const _w=ACT.web;ACT.web=function(){_w();const row=$("#fIn .row.between");if(row&&!row.querySelector("[data-act=webList]"))row.insertAdjacentHTML("beforeend",`<button class="sm" data-act="webList">Als Liste</button>`)}})();
ACT.tutorHelp=()=>{const sh=$("#sheet"),inn=$("#sheetIn");inn.innerHTML=`<div class="row between"><div class="eyebrow">Rollenspiel <span class="en">needs Claude</span></div><button class="icon ghost" data-act="closeSheet">${ic("x")}</button></div><h3>Rollenspiel mit Claude</h3><p>Im Rollenspiel spielt Claude Patienten, Oberärzte oder Beamte und antwortet frei. Dafür braucht die App Claude: in der claude.ai-Version funktioniert es sofort; in der installierten App trägst du unter <b>Ich → Einstellungen → Tutor</b> einen eigenen API-Schlüssel ein.</p><p class="muted ui">Ohne Claude: die <b>Abzweigungen</b> (Gespräche mit Weichen) und die <b>FSP-Simulation</b> mit Patient zum Ausfragen funktionieren offline.</p><div class="row wrap"><button class="primary" data-act="abzw">Abzweigungen</button><button class="sm" data-act="fsp">FSP-Simulation</button><button class="sm ghost tu-set">Zu den Einstellungen</button></div>`;sh.hidden=false;$(".tu-set",inn).onclick=()=>{closeSheet();go("me");setTimeout(()=>{const b=$("[data-act=meSeg][data-k=set]");if(b)b.click()},80)}};
(function(){MOD.after("viewPractice","fix",function(m){if(!SAMPLE){const r=m.querySelector(".tile[data-act=roleplay]");if(r){r.classList.remove("need-tutor","tutor");r.dataset.act="tutorHelp";const sm=r.querySelector("small");if(sm)sm.textContent="mit Claude · offline: Abzweigungen"}}})})();
GRAMMAR.forEach(g=>{if(typeof g.body==="string")g.body=g.body.replace(/\b(in|from|In|From|see|See|like in|as in|wie in|aus)\s+g(\d{1,2})\b/g,(m,pre,n)=>{const L=GRAMMAR.find(x=>x.id==="g"+n);return L?pre+" „"+L.title+"“":m})});

// ---- 18. exam dates pull the plan forward: if the remaining weeks don't fit before the exam, offer to skip ahead
function planFit(){const ex=[["goethe","Goethe B2",32],["fsp","FSP",40]].map(([k,n,endW])=>{const c=typeof examCountdown==="function"?examCountdown(k):null;return c&&c.days>0?{k,n,endW,weeks:Math.floor(c.days/7)}:null}).filter(Boolean).sort((a,b)=>a.weeks-b.weeks)[0];
  if(!ex)return null;const w=weekNumber();const need=ex.endW-w;if(need<=ex.weeks)return null;const target=Math.max(w+1,Math.min(ex.endW,ex.endW-ex.weeks));return {ex,target,need}}
ACT.planFit=()=>{const f=planFit();if(!f)return;const keepDay=weekDay();S.startDate=addDays(todayKey(),-((f.target-1)*7+keepDay-1));S.today=null;logEvent("plan","Plan vorgezogen auf Woche "+f.target+" ("+f.ex.n+")");saveSoon();toast("Plan ab Woche "+f.target);go("home")};
(function(){const _wh=wegHTML;wegHTML=function(){let h=_wh();const f=planFit();if(f)h=h.replace('<div class="lvbars">',`<div class="tch-merke" style="font-size:.9rem"><b>${esc(f.ex.n)} in ${f.ex.weeks} Wochen</b> – der Plan bräuchte bis dahin noch ${f.need}. Vorziehen auf Woche ${f.target}? Die übersprungenen Lektionen bleiben unter Lernen erreichbar.<div class="row" style="margin-top:.4rem"><button class="sm primary" data-act="planFit">Plan vorziehen</button></div></div><div class="lvbars">`);return h}})();
// feedback appears below the fold after Vergleichen / Abgeben / Prüfen: bring it into view
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest(".ft-go,.ex-chk,.wr-go,.te-go");if(!b)return;const scope=b.closest(".stack,.card,#fIn")||document;setTimeout(()=>{const out=(scope.querySelector&&scope.querySelector(".ft-out > *,.ex-out > *,.wr-out > *,.te-out > *"))||$("#fIn .ex-out > *");if(out&&out.getBoundingClientRect().top>innerHeight*.7)out.scrollIntoView({behavior:"smooth",block:"start"})},450)},true);

// ---- 19. telc Medizin: parts beyond the first of each module, shown only when round-2 content exists for them
(function(){const E=typeof EXAMS!=="undefined"&&EXAMS.med;const S2=(typeof EXAM_SEEDS2!=="undefined"&&EXAM_SEEDS2.med)||{};if(!E)return;
  const NEW=[["mH2","Hören","Teil 2","Arzt-Patienten-Gespräch / Visite",10,"listen","mH1"],["mH3","Hören","Teil 3","Telefonat und Konsil",10,"listen","mH2"],["mH4","Hören","Teil 4","Kurzvortrag / Fortbildung",12,"listen","mH3"],
   ["mL2","Lesen","Teil 2","Fachartikel / Patienteninformation",20,"mc","mL1"],["mL3","Lesen","Teil 3","Selektives Lesen: Anzeigen und Hinweise",15,"match","mL2"],["mB2","Lesen","Sprachbausteine 2","Klinischer Text mit Wortkasten",15,"gap","mB1"]];
  NEW.forEach(([id,m,t,title,min,type,after])=>{const seed=S2[id]||[];if(!seed.length||E.teile.some(x=>x.id===id))return;const i=E.teile.findIndex(x=>x.id===after);const spec=(seed[0]&&seed[0].partSpec)||title;E.teile.splice(i<0?E.teile.length:i+1,0,{id,m,t,title,min,type,spec,seed:seed.slice()})})})();

// ---- 0b. second pass of the audit corrections for items built further up in this file (rule cards for g17–g30, SATZ2, the term bank, exercise patches)
if(typeof TEXT_FIX!=="undefined"&&TEXT_FIX._miss&&TEXT_FIX._miss.length){const r=applyTextFix(TEXT_FIX._miss);TEXT_FIX._ok+=r.ok;TEXT_FIX._miss=r.miss.map(x=>x[0]+":"+x[1])}

// ================= KOMPASS (11.4): how Germany works — hospital system, clinical practice, life & culture =================
// Lessons come from content/out/r2_kompass_*.json (KOMPASS). Each compares Germany with Saudi Arabia and the USA.
const KOMPASS_GROUPS=[["system","Das Krankenhaus-System","Hierarchie, Ausbildung, Recht, Geld","steth"],["praxis","Klinischer Alltag & Kultur","Kommunikation, Recht am Bett, Medikamente","chat"],["zna","Notaufnahme kompakt","Recht und Abläufe, die du in der ZNA ab Tag 1 brauchst","bolt"],["leben","Leben in Deutschland","Ankommen, Wohnen, Menschen, Feste, Staat","sun"]];
const KP=()=>typeof KOMPASS!=="undefined"?KOMPASS:[];
const kpDone=id=>(S.kompass||{})[id];
// first weeks: arrival and ZNA basics in this order, then alternate hospital / clinic / life, easiest level first
const KP_FIRST=["kl1","kh18","kh5","kh2","kl2","kh14","kh13","kh15","kp1","kl3"];
function kompassNext(){const cap=typeof levelCap==="function"?levelCap():2;const L=KP().filter(k=>!kpDone(k.id)&&LV(k.level||"B1")<=cap+1);if(!L.length)return null;
  const f=KP_FIRST.map(id=>L.find(k=>k.id===id)).find(Boolean);if(f)return f;
  const n=Object.keys(S.kompass||{}).length;const want=["system","zna","praxis","leben"][n%4];const byLv=(a,b)=>LV(a.level||"B1")-LV(b.level||"B1");return L.filter(k=>k.group===want).sort(byLv)[0]||L.slice().sort(byLv)[0]}
// Kompass "+" terms get their own small budget: max 5 new per day, first seen tomorrow (no review snowball)
function kpSchedule(){S.kpSched=S.kpSched||{};const t=todayKey();Object.keys(S.kpSched).forEach(k=>{if(k<t)delete S.kpSched[k]});for(let i=1;i<60;i++){const d=addDays(t,i);if((S.kpSched[d]||0)<5){S.kpSched[d]=(S.kpSched[d]||0)+1;return d}}return addDays(t,1)}
function kpState(){const st=newState();st.due=kpSchedule();st.kp=1;return st}
function kpStats(){const all=KP(),d=all.filter(k=>kpDone(k.id));const sc=d.map(k=>kpDone(k.id).score).filter(x=>x!=null);const terms=Object.keys(S.cards||{}).filter(k=>S.cards[k]&&S.cards[k].kp).length;
  return {all:all.length,done:d.length,avg:sc.length?Math.round(sc.reduce((a,b)=>a+b,0)/sc.length):null,terms,groups:KOMPASS_GROUPS.map(g=>({g:g[0],name:g[1],n:all.filter(k=>k.group===g[0]).length,d:d.filter(k=>k.group===g[0]).length}))}}
ACT.kompass=()=>{if(Focus.isOpen())Focus.close(true);const box=Focus.open({title:"Kompass",sub:"Deutschland verstehen"});const all=KP();const done=all.filter(k=>kpDone(k.id)).length;
  box.innerHTML=`<div class="stack s"><p class="muted">Wie deutsche Krankenhäuser und der deutsche Alltag funktionieren – jedes Thema im Vergleich mit Saudi-Arabien und den USA, mit den Begriffen und Sätzen, die du brauchst.</p><div class="row between ui"><span>${done} / ${all.length} gelesen</span><span class="pbar" style="flex:1;margin-left:.6rem"><i style="width:${all.length?Math.round(100*done/all.length):0}%"></i></span></div>
  ${KOMPASS_GROUPS.map(([g,n,sub,icon])=>{const L=all.filter(k=>k.group===g);if(!L.length)return "";return `<div class="eyebrow" style="margin-top:.4rem">${ic(icon)} ${esc(n)} <span class="en">${esc(sub)}</span></div><div class="list">${L.map((k,i)=>{const d=kpDone(k.id);return `<button class="li" data-act="kompassOpen" data-id="${k.id}"><span class="n" style="${d?"background:var(--o);color:#fff":""}">${d?"✓":i+1}</span><span class="t"><b>${esc(k.title)}</b><small>${esc(k.sub||"")}</small></span><span class="m"><span class="pill lv lv-${k.level||"B1"}">${k.level||"B1"}</span></span></button>`}).join("")}</div>`}).join("")}</div>`};
ACT.kompassOpen=el=>{const k=KP().find(x=>x.id===(el.dataset?el.dataset.id:el));if(!k)return;const fromList=Focus.isOpen()&&!!$("#focus [data-act=kompassOpen]");if(Focus.isOpen())Focus.close(true);kompassView(Focus.open({title:"Kompass",sub:k.title}),k);if(fromList)FOCUS_BACK=()=>ACT.kompass()};
function kompassView(box,k,o){o=o||{};const G=KOMPASS_GROUPS.find(g=>g[0]===k.group)||KOMPASS_GROUPS[0];const gk=glossKey(Object.fromEntries((k.terms||[]).map(t=>[String(t[0]).replace(/^(der|die|das) /,""),t[1]])));
  box.innerHTML=`<div class="stack s kp"><div class="head"><div class="row wrap" style="gap:.35rem"><span class="pill">${esc(G[1])}</span><span class="pill lv lv-${k.level||"B1"}">${k.level||"B1"}</span></div><h1>${esc(k.title)}</h1><p>${esc(k.sub||"")}</p></div>
   <div class="card prose kp-body">${k.body||""}</div>
   ${(k.compare||[]).length?`<div class="card"><div class="eyebrow">Im Vergleich <span class="en">Germany · Saudi Arabia · USA</span></div><div class="kp-cmp"><table><thead><tr><th></th><th>Deutschland</th><th>Saudi-Arabien</th><th>USA</th></tr></thead><tbody>${k.compare.map(r=>`<tr><th>${esc(r.topic)}</th><td class="kp-de">${esc(r.de)}</td><td>${esc(r.sa)}</td><td>${esc(r.us)}</td></tr>`).join("")}</tbody></table></div></div>`:""}
   ${(k.terms||[]).length?`<div class="card"><div class="eyebrow">Begriffe <span class="en">tap + to add to your deck · max. 5 new a day, from tomorrow</span></div><div class="list">${k.terms.map(t=>`<div class="li" style="cursor:default;align-items:flex-start"><span class="t"><b>${deHTML?deHTML(t[0]):esc(t[0])}</b><small>${esc(t[1])}${t[2]?" · "+esc(t[2]):""}</small></span><span class="m"><button class="icon ghost" data-say="${esc(t[0])}">${ic("vol")}</button><button class="sm kp-add" data-de="${esc(t[0])}" data-en="${esc(t[1])}" data-info="${esc(t[2]||"")}">${ic("plus")}</button></span></div>`).join("")}</div></div>`:""}
   ${(k.phrases||[]).length?`<div class="card"><div class="eyebrow">So sagst du es <span class="en">phrases</span></div><div class="list">${k.phrases.map(p=>`<div class="li" style="cursor:default;align-items:flex-start"><span class="t"><b class="de" data-gk="${gk}">${glossify(p[0])}</b><small>${esc(p[1])}</small></span><span class="m"><button class="icon ghost" data-say="${esc(p[0])}">${ic("vol")}</button></span></div>`).join("")}</div></div>`:""}
   ${(k.dialog||[]).length?`<div class="card"><div class="eyebrow">Gespräch <span class="en">hold a word to translate</span></div><div class="dl">${k.dialog.map(d=>`<div class="turn ${/Ismail|^Du$|Amron/.test(d[0])?"me":""}"><div class="who"><span>${esc(d[0])}</span><button data-say="${esc(d[1])}">${ic("vol")}</button></div><div data-gk="${gk}">${glossify(d[1])}</div><div class="tr" hidden>${esc(d[2]||"")}</div></div>`).join("")}</div><button class="sm ghost kp-tr">Übersetzung</button></div>`:""}
   ${(k.pitfalls||[]).length?`<div class="card"><div class="eyebrow">Was überrascht <span class="en">pitfalls</span></div><ul>${k.pitfalls.map(p=>`<li>${esc(p)}</li>`).join("")}</ul></div>`:""}
   ${k.merke?`<div class="tch-merke"><b>Merke:</b> <span class="de">${esc(k.merke)}</span></div>`:""}
   ${(k.quiz||[]).length?`<div class="card kp-quiz"></div>`:""}
   ${(k.sources||[]).length?`<details class="card"><summary class="ui">Quellen</summary><ul>${k.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title||s.url)}</a></li>`).join("")}</ul></details>`:""}
   <div class="row"><button class="primary kp-done">${kpDone(k.id)?"Nochmal gelesen":"Gelesen"}</button>${o.session?"":`<button class="sm ghost" data-act="kompass">Alle Themen</button>`}</div></div>`;
  const tr=$(".kp-tr",box);if(tr)tr.onclick=()=>$$(".kp .tr",box).forEach(x=>x.hidden=!x.hidden);
  $$(".kp-add",box).forEach(b=>b.onclick=()=>{const de=b.dataset.de;const id="w:"+de;if(S.cards[id]||S.custom.some(c=>c.de===de))return toast("Schon im Deck");const st=kpState();if(CATALOG.has(id))S.cards[id]=st;else{S.custom.push({de,en:b.dataset.en,ex:"",info:b.dataset.info||"",tag:"kompass"});buildDict();S.cards["c:"+(S.custom.length-1)]=st}saveSoon();b.disabled=true;b.innerHTML=ic("check");const dd=st.due===addDays(todayKey(),1)?"morgen":fmtDate?fmtDate(st.due):st.due;toast("Ins Deck · zum ersten Mal "+dd)});
  let score=null;const qb=$(".kp-quiz",box);if(qb){let i=0,right=0;const Q=k.quiz;const step=()=>{if(i>=Q.length){score=Math.round(100*right/Q.length);qb.innerHTML=`<div class="row between"><b class="ui">Quiz</b><span class="pill ${score>=80?"good":"o"}">${right} / ${Q.length}</span></div>`;return}const q=Q[i];
      qb.innerHTML=`<div class="q"><div class="eyebrow">Frage ${i+1} / ${Q.length}</div><div class="stem">${esc(q.q)}</div><div class="opts">${shuffle(q.o.map((t,j)=>[t,j])).map(([t,j])=>`<button data-j="${j}">${esc(t)}</button>`).join("")}</div><div class="kp-why"></div></div>`;
      $$(".opts [data-j]",qb).forEach(b=>b.onclick=()=>{if($(".kp-why",qb).innerHTML)return;const ok=+b.dataset.j===q.a;if(ok)right++;fb(ok);b.classList.add(ok?"right":"wrong");if(!ok){const r=$(`.opts [data-j="${q.a}"]`,qb);if(r)r.classList.add("right")}$(".kp-why",qb).innerHTML=`<div class="verdict ${ok?"ok":"no"}" data-noxp="1">${esc(q.why||"")}<div class="row" style="margin-top:.5rem"><button class="primary kp-nx">Weiter</button></div></div>`;$(".kp-nx",qb).onclick=()=>{i++;step()}})};step()}
  $(".kp-done",box).onclick=()=>{S.kompass=S.kompass||{};S.kompass[k.id]={date:todayKey(),score};logDay("read");logEvent("read","Kompass: "+k.title+(score!=null?" · Quiz "+score+" %":""),score);saveSoon();toast("Gespeichert");if(o.onDone)o.onDone(score);else ACT.kompass()}}
// progress in Ich → Fortschritt and in "Krankenhausreif?"
(function(){MOD.after("viewMe","kompass",function(m){if(!KP().length||typeof meSeg==="undefined"||meSeg!=="fort"||m.querySelector(".kp-prog"))return;const P=kpStats();const kr=[...m.querySelectorAll(".card h3")].find(h=>/Krankenhausreif/.test(h.textContent));
    const sysD=P.groups.filter(g=>g.g!=="leben").reduce((a,g)=>a+g.d,0),sysN=P.groups.filter(g=>g.g!=="leben").reduce((a,g)=>a+g.n,0);
    if(kr){const cl=kr.parentElement.querySelector(".check-list");if(cl)cl.insertAdjacentHTML("beforeend",`<div>${sysD>=sysN?`<span class="ok">${ic("check")}</span>`:`<span class="muted">○</span>`}<span>Kompass: Krankenhaus-System, Klinik &amp; ZNA gelesen (${sysD} / ${sysN})</span></div>`)}
    const html=`<button class="card stack s kp-prog" data-act="kompass" style="text-align:left;width:100%"><div class="row between"><h3 style="margin:0">Kompass</h3><span class="pill">${P.done} / ${P.all}</span></div>${P.groups.map(g=>`<div class="ui" style="font-size:.85rem">${esc(g.name)} <span class="muted">${g.d}/${g.n}</span><span class="pbar"><i style="width:${g.n?Math.round(100*g.d/g.n):0}%"></i></span></div>`).join("")}<div class="muted ui" style="font-size:.85rem">Quiz Ø ${P.avg!=null?P.avg+" %":"–"} · ${P.terms} Begriffe im Deck</div></button>`;
    if(kr)kr.parentElement.insertAdjacentHTML("beforebegin",html);else{const v=m.querySelector(".view");if(v)v.insertAdjacentHTML("beforeend",html)}})})();
// entry points: Lernen card, Heute suggestion, deep link ?a=kompass:<id>
(function(){MOD.after("viewLearn","kompass",function(m){if(!KP().length||m.querySelector(".kp-entry"))return;const head=m.querySelector(".ws-entry")||m.querySelector(".view .head");if(!head)return;const done=KP().filter(k=>kpDone(k.id)).length;
    head.insertAdjacentHTML("afterend",`<button class="li kp-entry" data-act="kompass"><span class="ic">${ic("target")}</span><span class="t"><b>Kompass: Deutschland verstehen</b><small>Krankenhaus-System, klinischer Alltag, Leben in Deutschland · ${done}/${KP().length}</small></span>${ic("chev")}</button>`)})
  MOD.after("viewHome","kompass",function(m){const n=kompassNext();if(!n||m.querySelector(".kp-home"))return;const anchor=m.querySelector(".wdt")||m.querySelector(".weg");if(!anchor)return;
    anchor.insertAdjacentHTML("afterend",`<button class="card li kp-home" data-act="kompassOpen" data-id="${n.id}" style="text-align:left"><span class="ic">${ic("target")}</span><span class="t"><span class="eyebrow">Kompass <span class="en">Deutschland verstehen</span></span><b>${esc(n.title)}</b><small>${esc(n.sub||"")}</small></span>${ic("chev")}</button>`)})
  const _dl=typeof runDeepLink==="function"?runDeepLink:null;if(_dl)runDeepLink=function(){let a=null;try{a=new URLSearchParams(location.search).get("a")}catch(e){}const m=String(a||"").match(/^kompass(?::(.+))?$/);if(m){try{history.replaceState(history.state,"",location.pathname+location.hash)}catch(e){}if(m[1])ACT.kompassOpen(m[1]);else ACT.kompass();return true}return _dl()}})();

// ================= 11.4 — design & usability fixes from the round-2 UX review (05/11/2026) =================
// 1 placement no longer back-dates the plan (week offset instead) · 2 history: Back moves between tabs/lessons ·
// 3 Classic look by default · 4 skipped steps aren't counted · 5 Heute: steps right under the hero · 6 lesson page
// without library chrome, Klinik list in week order · 7 Üben "Für dich" row · 8 small fixes (minutes, welcome text,
// toasts, map list on phones, Stufenprüfung label, Behalten hint)

// ---- 1. plan position = real days + an offset in weeks (set by placement or "Plan vorziehen")
(function(){if(S.placed&&S.weekOffset==null){const logDays=Object.keys(S.log||{}).sort();const real=[logDays[0],S.placed].filter(Boolean).sort()[0]||todayKey();
    if(real>S.startDate){const wasWeek=weekNumber();S.startDate=real;S.weekOffset=Math.max(0,wasWeek-Math.ceil(dayNumber()/7));saveSoon()}else S.weekOffset=0}})();
weekNumber=()=>clamp(Math.ceil(dayNumber()/7)+(S.weekOffset||0),1,WEEKS.length);
function setPlanWeek(w){S.weekOffset=Math.max(0,w-Math.ceil(dayNumber()/7));S.today=null;saveSoon()}
// placement and plan-fit now move the offset, not the start date
(function(){const P=typeof PLACE!=="undefined"?PLACE:null;if(!P)return;placeWire=function(root,done){let lv=S.placement||"",mn=S.minutes;const go2=$(".place-go",root);
  $$(".place-o",root).forEach(b=>b.onclick=()=>{lv=b.dataset.l;$$(".place-o",root).forEach(x=>x.classList.toggle("on",x===b));go2.disabled=false});
  $$(".place-min button",root).forEach(b=>b.onclick=()=>{mn=+b.dataset.n;$$(".place-min button",root).forEach(x=>x.classList.toggle("on",x===b))});
  const x=$(".place-x",root);if(x)x.onclick=()=>done&&done(false);
  go2.onclick=()=>{const p=P.find(q=>q[0]===lv);if(!p)return;const prev=S.placement;S.placement=lv;S.wdt=null;S.placed=S.placed||todayKey();S.minutes=mn;setPlanWeek(prev===lv?Math.max(p[3],weekNumber()):p[3]);if(lv==="C1"&&S.focus!=="pruefung")S.focus="pruefung";S.today=null;
    logEvent("plan","Einstufung "+lv+" · "+mn+" Min./Tag · ab Woche "+weekNumber());saveSoon();toast("Plan ab Woche "+weekNumber()+" · "+lv);if(done)done(true)}}})();
if(typeof ACT.planFit==="function")ACT.planFit=()=>{const f=planFit();if(!f)return;setPlanWeek(f.target);logEvent("plan","Plan vorgezogen auf Woche "+f.target+" ("+f.ex.n+")");toast("Plan ab Woche "+f.target);go("home")};
// level shown honestly next to a self-placement: levels up to the placement count as "selbst eingestuft"
(function(){const _le=levelEstimate;levelEstimate=function(){const e=_le();const P=S.placement;if(!P)return e;const p=LV(P);if(p>LV(e.reached==="A0"?"A1":e.reached)||e.reached==="A0"){const nx=LEVELS[Math.min(4,p+1)];return Object.assign({},e,{stufe:P,reached:P,next:nx,pct:Math.round(100*((e.prog[nx]||{p:0}).p||0)),self:true})}return e}})();

// ---- 2. Back/forward move through tabs and lesson pages (overlays keep their own guard in c_fix)
(function(){let popping=false;const _go=go;go=function(tab,arg){const r=_go(tab,arg);if(!popping){try{const st={tab:typeof tab==="string"?tab:"home",arg:arg||null};const cur=history.state||{};if(cur.tab!==st.tab||cur.arg!==st.arg||cur.mf)history.pushState(st,"","#"+st.tab+(st.arg?"/"+encodeURIComponent(st.arg):""))}catch(e){}}return r};
  try{if(!history.state||!history.state.tab)history.replaceState({tab:"home",arg:null},"",location.hash||"#home")}catch(e){}
  addEventListener("popstate",e=>{const st=e.state||{};const fo=$("#focus"),sh=$("#sheet");if((fo&&!fo.hidden)||(sh&&!sh.hidden)||st.mf)return;if(st.tab){popping=true;try{go(st.tab,st.arg||undefined)}finally{popping=false}}});
  addEventListener("hashchange",()=>{const h=location.hash.replace(/^#/,"");const [t,a]=h.split("/");if(/^(home|learn|practice|me)$/.test(t)&&!(history.state&&history.state.tab===t&&(history.state.arg||null)===(a?decodeURIComponent(a):null))){popping=true;try{go(t,a?decodeURIComponent(a):undefined)}finally{popping=false}}})})();

