// ---- 4/5. Heute: skipped steps don't count, the step list sits right under the session button, the welcome text counts real steps
(function(){MOD.after("viewHome","ux",function(m){const T=S.today;if(!T)return;
  const skipped=T.steps.filter(s=>s.skipped).length;const done=T.steps.filter(s=>s.done&&!s.skipped).length;
  $$(".step",m).forEach((b,i)=>{const s=T.steps[+b.dataset.i];if(s&&s.skipped){b.classList.remove("done");b.classList.add("skipped");const icn=b.querySelector(".ic");if(icn)icn.innerHTML="–";const st=b.querySelector(".st");if(st)st.textContent="später nachholen"}});
  const ring=m.querySelector(".ring text");if(ring&&/\d+\s*\/\s*\d+/.test(ring.textContent))ring.textContent=done+"/"+T.steps.length;
  const steps=m.querySelector(".steps");const hero=m.querySelector(".hero");if(steps&&hero){const card=steps.closest(".card")||steps;if(hero.nextElementSibling!==card)hero.after(card)}
  const wl=[...m.querySelectorAll(".prose li,.card li")].find(li=>/sechs kurze Schritte/.test(li.textContent));if(wl)wl.innerHTML=wl.innerHTML.replace("sechs kurze Schritte",({3:"drei",4:"vier",5:"fünf",6:"sechs"})[T.steps.length]+" kurze Schritte")})})();

