// ===== Mephisto 12.1 · Mephistos Werkstatt: gender sigils, Gedächtnispalast, Merkmärchen, Schattenarbeit, Erklär-es-dem-Teufel, Rezitation, Bibliothek, Medien
const LVN=["A1","A2","B1","B2","C1"];
function lvIdx(s){const m=String(s||"").match(/[ABC][12]/);return m?LVN.indexOf(m[0]):0}
function pkCheck(out,text,t){t=Object.assign({t:"Text",task:"",reg:"",check:[],model:""},t||{});
  if(typeof SAMPLE!=="undefined"&&SAMPLE&&typeof correct==="function"){out.innerHTML=`<p class="muted ui pk-flicker">Mephisto liest Ihren Text …</p>`;correct(text,t.task||t.t,t.reg||"neutral").then(r=>renderCorrection(out,text,r,t)).catch(()=>selfCheck(out,text,t,{}))}
  else selfCheck(out,text,t,{})}
