// ---------------------------------------------------------------- 1. Genus-Siegel everywhere
const SIG_SKIP="INPUT,TEXTAREA,SCRIPT,STYLE,SELECT,BUTTON,A,H1,H2,H3,H4,LABEL,small,.pill,.muted,.ui,.toast,.pk-say,.omen,.hero,.pk-seal,.eyebrow,.chip,nav,.werk-grid,.bib-grid,.no-sig,.g-der,.g-die,.g-das,.tch,.pk-faust";
function sigilize(root){if(!root||S.sigils===false||typeof tGenus!=="function")return;
  // glossified text: <span class="w">der</span> <span class="w">Tisch</span>
  root.querySelectorAll("span.w").forEach(a=>{const art=a.textContent;if(a.closest(".no-sig")||!/^(der|die|das|Der|Die|Das)$/.test(art)||a.dataset.sg)return;let n=a.nextSibling;while(n&&n.nodeType===3&&!n.textContent.trim())n=n.nextSibling;
    if(!n||n.nodeType!==1||!n.classList||!n.classList.contains("w"))return;const noun=n.textContent;if(!/^[A-ZÄÖÜ]/.test(noun))return;const g=tGenus(noun);if(g!==art.toLowerCase())return;
    a.dataset.sg=1;a.classList.add("g-"+g);n.classList.add("g-"+g);a.insertAdjacentHTML("afterbegin",`<i class="sig ${g}"></i>`)});
  const tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:t=>{const p=t.parentElement;if(!p||p.closest(SIG_SKIP)||p.closest("span.w"))return NodeFilter.FILTER_REJECT;return /\b(der|die|das|Der|Die|Das)\s+[A-ZÄÖÜ]/.test(t.textContent)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
  const nodes=[];while(tw.nextNode())nodes.push(tw.currentNode);
  nodes.slice(0,400).forEach(t=>{const s=t.textContent;let changed=false;const html=esc(s).replace(/\b(der|die|das|Der|Die|Das)(\s+)([A-ZÄÖÜ][a-zäöüß]+)/g,(m,a,sp,n)=>{const g=tGenus(n);if(g!==a.toLowerCase())return m;changed=true;return `<span class="g-${g}"><i class="sig ${g}"></i>${a}</span>${sp}<span class="g-${g}">${n}</span>`});
    if(!changed)return;const sp=document.createElement("span");sp.innerHTML=html;t.replaceWith(...sp.childNodes)})}
let SIG_T=null;const SIG_Q=new Set();
new MutationObserver(ms=>{if(S.sigils===false)return;for(const m of ms)m.addedNodes.forEach(n=>{if(n.nodeType===1)SIG_Q.add(n);else if(n.nodeType===3&&n.parentElement)SIG_Q.add(n.parentElement)});clearTimeout(SIG_T);SIG_T=setTimeout(()=>{const L=[...SIG_Q];SIG_Q.clear();L.forEach(el=>{if(el.isConnected&&el.closest&&el.closest("#main,#fIn,#sheetIn,#pakt-rail"))try{sigilize(el)}catch(e){}})},140)}).observe(document.body,{childList:true,subtree:true});
// ---------------------------------------------------------------- 2. Gedächtnispalast (gender rooms)
function palRule(noun){for(const r of PALACE.rules)if(r.re.test(noun))return r;return null}
function palNouns(n){const lv=typeof learnerLv==="function"?learnerLv():0;const all=allCards().filter(c=>/^(der|die|das) [A-ZÄÖÜ][^\s]+$/.test(c.de));
  const pal=S.palace||{};const seen=all.filter(c=>S.cards[c.id]);const lvl=all.filter(c=>!S.cards[c.id]&&lvIdx(c.level)<=lv+1);
  const weak=all.filter(c=>pal[c.de.split(" ")[1]]&&pal[c.de.split(" ")[1]].miss>pal[c.de.split(" ")[1]].ok);
  const pick=(arr,k)=>arr.slice().sort(()=>Math.random()-.5).slice(0,k);const out=[...pick(weak,Math.ceil(n*.3)),...pick(seen,Math.ceil(n*.4)),...pick(lvl,n)];
  const u=new Map();out.forEach(c=>u.set(c.de,c));return [...u.values()].slice(0,n)}
function mnemoFor(word){const w=String(word).toLowerCase();return MNEMO.find(m=>m.k.toLowerCase().split(/\s*[·,]\s*|\s+≠\s+/).some(x=>x.replace(/^(der|die|das)\s+/,"")===w.replace(/^(der|die|das)\s+/,"")))}
ACT.palace=()=>{const items=palNouns(16);if(!items.length)return toast("Keine Nomen gefunden.");let i=0,ok=0;const box=Focus.open({title:"Gedächtnispalast",sub:"Fausts Haus · der · die · das"});
  const door=g=>{const P=PALACE[g],a=pkArt(P.art);return `<button class="pal-door" data-g="${g}" style="--c:${P.col}">${a?`<img src="${a.u}" alt="" class="k-${a.k}">`:""}<span><b><i class="sig ${g}"></i>${g}</b><small>${esc(P.room)}</small></span></button>`};
  const intro=()=>{box.innerHTML=`<div class="stack" style="max-width:680px;margin:0 auto"><div class="card orn">${pkSay(["Jedes Nomen hat ein Zimmer in Fausts Haus. Merken Sie sich den Ort, dann vergessen Sie nie wieder den Artikel.","Every noun has a room in Faust's house. Remember the place and you'll never forget the article again."])}</div>
    ${["der","die","das"].map(g=>`<div class="card stack s" style="border-left:3px solid ${PALACE[g].col}"><div class="eyebrow"><i class="sig ${g}"></i>${g} · ${esc(PALACE[g].room)}</div><p class="pk-nar">${esc(PALACE[g].scene)}</p></div>`).join("")}
    <details class="card"><summary class="ui"><b>Die Regeln der Räume</b> · suffixes that decide the room</summary><div class="stack s" style="margin-top:.5rem">${PALACE.rules.map(r=>`<div><b class="g-${r.g}"><i class="sig ${r.g}"></i>${r.g}</b> ${esc(r.r)}<br><small class="muted ui">${esc(r.ex)}</small></div>`).join("")}</div></details></div>`;
    Focus.foot(`<button class="go" data-act="palGo">Rundgang beginnen · ${items.length} Nomen</button>`)};
  const ask=()=>{Focus.progress({n:items.length,i});const c=items[i];const [g,noun]=c.de.split(" ");
    box.innerHTML=`<div class="stack" style="max-width:680px;margin:0 auto;text-align:center"><div class="eyebrow">In welches Zimmer gehört …</div><div style="font-family:var(--display);font-size:clamp(2.2rem,9vw,3.4rem);line-height:1.1" class="no-sig">${esc(noun)}</div><div class="muted ui">${esc(c.en||"")}${c.pl?` · Pl. ${esc(c.pl)}`:""}</div>
     <div class="pal-doors">${door("der")}${door("die")}${door("das")}</div><div id="palOut"></div></div>`;Focus.foot(null);
    box.querySelectorAll(".pal-door").forEach(b=>b.onclick=()=>answer(b.dataset.g))};
  const answer=pick=>{const c=items[i];const [g,noun]=c.de.split(" ");const right=pick===g;S.palace=S.palace||{};const st=S.palace[noun]=S.palace[noun]||{g,ok:0,miss:0};right?st.ok++:(st.miss++,st.wrong=pick);st.d=todayKey();if(right)ok++;saveSoon();
    SND.fx(right?"ok":"no");fb&&fb(right);const P=PALACE[g];const put=P.put[Math.floor(Math.random()*P.put.length)].replace("{X}",`<b class="g-${g} no-sig"><i class="sig ${g}"></i>${g} ${esc(noun)}</b>`);const r0=palRule(noun);const r=r0&&r0.g===g?r0:null;const mn=mnemoFor(c.de);
    box.querySelectorAll(".pal-door").forEach(b=>{b.disabled=true;if(b.dataset.g===g)b.classList.add("right");else if(b.dataset.g===pick)b.classList.add("wrong")});
    $("#palOut").innerHTML=`<div class="card stack s pk-fade no-sig" style="text-align:left;margin-top:1rem">${right?"":pkSay(pkMephLine("wrong"))}<div class="eyebrow">${esc(P.room)}</div><p class="pk-nar" style="color:var(--fg)">${put}</p>
      ${r?`<p class="ui" style="font-size:.9rem"><b>Regel:</b> ${esc(r.r)}${r.weak?" <span class='muted'>(nicht immer!)</span>":""}</p>`:""}${r0&&!r?`<p class="ui" style="font-size:.9rem"><b>Ausnahme!</b> ${esc(g+" "+noun)} folgt nicht der Regel „${esc(r0.r)}“.</p>`:""}${mn?`<p class="ui" style="font-size:.9rem"><b>Merkmärchen:</b> ${esc(mn.t)}</p>`:""}</div>`;
    Focus.foot(`<button class="go" data-act="palNext">${i<items.length-1?"Weiter":"Auswertung"}</button>`)};
  const done=()=>{Focus.progress(null);const pct=Math.round(100*ok/items.length);box.innerHTML=`<div class="stack" style="max-width:640px;margin:0 auto"><h2 style="text-align:center">${ok} von ${items.length}</h2><div class="card orn">${pkSay(pkMephLine(pct>=80?"right":"wrong"))}</div>
     <div class="card stack s"><div class="eyebrow">Dein Palast</div>${["der","die","das"].map(g=>{const L=Object.entries(S.palace||{}).filter(([n,v])=>v.g===g);return `<div><b class="g-${g}"><i class="sig ${g}"></i>${esc(PALACE[g].room)}</b> · ${L.length} Nomen<br><small class="muted ui">${L.slice(-14).map(([n,v])=>`${esc(n)}${v.miss>v.ok?" ✗":""}`).join(" · ")}</small></div>`}).join("")}</div></div>`;
    Focus.foot(`<button class="go" data-act="palace">Noch ein Rundgang</button>`);if(typeof completeTask==="function")try{completeTask("palace")}catch(e){}};
  ACT.palGo=()=>{i=0;ask()};ACT.palNext=()=>{i++;if(i<items.length)ask();else done()};intro()};
// ---------------------------------------------------------------- 3. Merkmärchen
ACT.mnemo=()=>{const box=Focus.open({title:"Merkmärchen",sub:"Kleine dunkle Geschichten gegen das Vergessen"});const types=[["genus","Genus"],["false","Falsche Freunde"],["rule","Regeln"],["med","Klinik"]];
  box.innerHTML=`<div class="stack" style="max-width:720px;margin:0 auto"><div class="card orn">${pkSay(["Was man mit Grauen lernt, vergisst man nicht. Glauben Sie mir, ich habe Erfahrung.","What you learn with horror, you never forget. Believe me, I have experience."])}</div>
   <input class="mn-q" placeholder="Suchen: Gabel, Dativ, bekommen …" style="width:100%">
   ${types.map(([k,n])=>`<div class="stack s mn-g" data-k="${k}"><div class="eyebrow">${n}</div>${MNEMO.filter(m=>m.type===k).map(m=>`<details class="card mn-i"><summary><b style="font-family:var(--body);font-size:1.05rem">${esc(m.k)}</b></summary><p class="pk-nar" style="margin-top:.5rem">${esc(m.t)}</p></details>`).join("")}</div>`).join("")}</div>`;
  const q=box.querySelector(".mn-q");q.oninput=()=>{const v=q.value.trim().toLowerCase();box.querySelectorAll(".mn-i").forEach(d=>{d.hidden=v&&!d.textContent.toLowerCase().includes(v);if(v&&!d.hidden)d.open=true})}};
// mnemonic on flash cards (card back meta)
if(typeof cardMeta==="function"){const _cm=cardMeta;cardMeta=function(c){let h=_cm.apply(this,arguments)||"";try{const m=c&&mnemoFor(c.de);if(m)h+=`<span class="cm-info" style="display:block;margin-top:.4rem">☩ ${esc(m.t)}</span>`}catch(e){}return h}}
// ---------------------------------------------------------------- 4. Schattenarbeit: your own recurring mistakes, spoken by your shadow
function shadowItems(){const out=[];const seen=new Set();
  (S.mistakes||[]).slice().reverse().forEach(m=>{const x=String(m.text||"").match(/\{\{c1::(.+?)\}\}\s*\(nicht:\s*(.+?)\)\s*$/);if(!x)return;const key=x[2]+"→"+x[1];if(seen.has(key)||(S.shadowDone||{})[key])return;seen.add(key);out.push({bad:x[2],good:x[1],why:m.extra||"",type:m.type||"",key})});
  Object.entries(S.palace||{}).filter(([n,v])=>v.miss>v.ok).forEach(([n,v])=>{const key="g:"+n;if((S.shadowDone||{})[key])return;out.push({bad:(v.wrong||["der","die","das"].filter(g=>g!==v.g)[0])+" "+n,good:v.g+" "+n,why:"Genus — "+PALACE[v.g].room,type:"Genus",key})});
  return out.slice(0,10)}
ACT.shadowWork=()=>{const items=shadowItems();const box=Focus.open({title:"Schattenarbeit",sub:"Der Schatten spricht deine Fehler"});
  if(!items.length){box.innerHTML=`<div class="stack" style="max-width:640px;margin:0 auto"><div class="card orn">${pkSay(["Ihr Schatten schweigt. Noch. Schreiben Sie mehr, machen Sie mehr Fehler — dann redet er.","Your shadow is silent. For now. Write more, make more mistakes — then he'll talk."])}</div><p class="muted ui">The shadow collects corrections from the writing coach and the Claude tutor, and nouns you put in the wrong room in the palace.</p></div>`;return}
  let i=0,ok=0;const norm=s=>String(s).toLowerCase().replace(/[.,!?;:„“"]/g,"").replace(/\s+/g," ").trim();
  const ask=()=>{Focus.progress({n:items.length,i});const it=items[i];box.innerHTML=`<div class="stack" style="max-width:640px;margin:0 auto">
     <div class="card" style="border-color:var(--bad)"><div class="pk-say"><div class="who n" style="filter:invert(1)">☗</div><div><div class="eyebrow" style="color:var(--bad)">Dein Schatten sagt</div><div class="de no-sig" style="font-family:var(--body);font-size:1.25rem">„${esc(it.bad)}“</div><div class="en">${esc(it.type)}</div></div></div></div>
     <label class="f">So sagt man es richtig:<input class="sh-in" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(it.bad)}"></label><div id="shOut"></div></div>`;
    Focus.foot(`<button class="go" data-act="shCheck">Prüfen</button>`);const inp=box.querySelector(".sh-in");inp.focus();inp.select();inp.onkeydown=e=>{if(e.key==="Enter")ACT.shCheck()}};
  ACT.shCheck=()=>{const it=items[i];const v=box.querySelector(".sh-in").value;const right=norm(v)===norm(it.good)||norm(v).includes(norm(it.good));if(right){ok++;S.shadowDone=S.shadowDone||{};S.shadowDone[it.key]=todayKey();saveSoon()}
    SND.fx(right?"ok":"no");$("#shOut").innerHTML=`<div class="card stack s pk-fade">${right?`<b style="color:var(--good)">Der Schatten weicht zurück.</b>`:`<b style="color:var(--bad)">Der Schatten lacht.</b>`}<div>Richtig: <b>${esc(it.good)}</b></div>${it.why?`<small class="muted ui">${esc(it.why)}</small>`:""}</div>`;
    Focus.foot(`<button class="go" data-act="shNext">${i<items.length-1?"Nächster Fehler":"Ende"}</button>`)};
  ACT.shNext=()=>{i++;if(i<items.length)ask();else{Focus.progress(null);box.innerHTML=`<div class="stack" style="max-width:640px;margin:0 auto"><h2 style="text-align:center">${ok} von ${items.length} Schatten gebannt</h2><div class="card orn">${pkSay(ok===items.length?["Ihr Schatten ist für heute still. Er kommt wieder.","Your shadow is quiet for today. He'll be back."]:pkMephLine("wrong"))}</div></div>`;Focus.foot(null)}};ask()};
// ---------------------------------------------------------------- 5. Erklär es dem Teufel (teach-back, Mephisto plays dumb)
ACT.teachDevil=()=>{const box=Focus.open({title:"Erklär es dem Teufel",sub:"Mephisto spielt den dummen Schüler"});
  box.innerHTML=`<div class="stack" style="max-width:640px;margin:0 auto"><div class="card orn">${pkSay(["Ich bin heute ein ganz dummer Schüler. Erklären Sie mir eine Regel – auf Deutsch, in einfachen Sätzen. Wenn ich es danach verstehe, haben Sie es auch verstanden.","Today I'm a very stupid student. Explain a rule to me — in German, simple sentences. If I understand it afterwards, so do you."])}</div>
   <div class="card">${pkSay(["Zum Beispiel: Warum sagt man „Ich gehe in den Keller“, aber „Ich bin im Keller“? Ich verstehe das nicht. Wirklich nicht. Hihi.","For example: why 'in den Keller' but 'im Keller'? I really don't get it. Hee hee."])}</div>
   <button class="go" data-act="teachGo">Eine Regel wählen</button></div>`;ACT.teachGo=()=>{Focus.close(true);ACT.teach()}};
// ---------------------------------------------------------------- 6. Rezitation: learn real poems by heart in four steps
function reziMask(text,stage){return text.split("\n").map(line=>{if(!line.trim())return "";if(stage===1)return esc(line);let k=0;
  return line.split(/(\s+)/).map(tok=>{if(/^\s+$/.test(tok)||!tok)return tok;const m=tok.match(/^([„"(]*)([A-Za-zÄÖÜäöüß'’-]+)(.*)$/);if(!m)return esc(tok);k++;
    if(stage===2)return esc(m[1])+`<span class="rz-h" title="${esc(m[2])}">${esc(m[2][0])}${"·".repeat(Math.max(0,m[2].length-1))}</span>`+esc(m[3]);
    if(stage===3&&k%2===0)return esc(m[1])+`<button class="rz-gap" data-w="${esc(m[2])}">${"_".repeat(Math.min(10,m[2].length))}</button>`+esc(m[3]);return esc(tok)}).join("")}).join("<br>")}
function reziDiff(a,b){const A=a.toLowerCase().replace(/[^a-zäöüß\s]/g," ").split(/\s+/).filter(Boolean),B=b.toLowerCase().replace(/[^a-zäöüß\s]/g," ").split(/\s+/).filter(Boolean);const n=A.length,m=B.length;const D=Array.from({length:n+1},()=>new Array(m+1).fill(0));
  for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)D[i][j]=A[i]===B[j]?D[i+1][j+1]+1:Math.max(D[i+1][j],D[i][j+1]);const hit=new Set();let i=0,j=0;while(i<n&&j<m){if(A[i]===B[j]){hit.add(i);i++;j++}else if(D[i+1][j]>=D[i][j+1])i++;else j++}const Araw=a.replace(/[^A-Za-zÄÖÜäöüß\s]/g," ").split(/\s+/).filter(Boolean);return {pct:n?Math.round(100*D[0][0]/n):0,A:Araw.length===n?Araw:A,hit}}
ACT.rezi=()=>{const box=Focus.open({title:"Rezitation",sub:"Auswendig lernen wie früher"});const R=S.rezi||{};
  box.innerHTML=`<div class="stack" style="max-width:720px;margin:0 auto"><div class="card orn">${pkSay(["In Deutschland lernte jedes Kind Gedichte auswendig. Ihre Kollegen können die Lorelei noch heute. Sie bald auch.","Every German child learned poems by heart. Your colleagues can still recite the Lorelei. Soon, so can you."])}</div>
   <p class="muted ui">Four steps: 1 read and listen · 2 first letters only · 3 every second word gone · 4 from memory (type or speak). Rhythm and rhyme glue grammar into your head.</p>
   ${REZI.map(p=>{const r=R[p.id];return `<button class="card" style="text-align:left;display:block" data-act="reziOpen" data-id="${p.id}"><div class="row between"><span class="eyebrow">${esc(p.lv)} · Reich ${esc(p.r)}</span>${r?`<span class="chip">${r.best||0} %</span>`:""}</div><div style="font-family:var(--display);font-size:1.35rem">${esc(p.t)}</div><small class="muted ui">${esc(p.a)} · ${esc(p.src)}</small></button>`}).join("")}</div>`};
ACT.reziOpen=el=>{const p=REZI.find(x=>x.id===el.dataset.id);if(!p)return;let stage=1;const box=Focus.open({title:p.t,sub:p.a,onClose:()=>ACT.rezi()});
  const draw=()=>{Focus.progress({n:4,i:stage-1});const tabs=[[1,"Lesen"],[2,"Anfänge"],[3,"Lücken"],[4,"Auswendig"]].map(([k,n])=>`<button class="${stage===k?"on":""}" data-rs="${k}">${k} ${n}</button>`).join("");
    box.innerHTML=`<div class="stack" style="max-width:640px;margin:0 auto"><div class="seg">${tabs}</div>
     ${stage<4?`<div class="card orn"><div class="pk-faust no-sig" style="font-style:normal;border:0;padding:0;line-height:1.75;font-size:1.12rem">${stage===1?glossify(p.text).replace(/\n/g,"<br>"):reziMask(p.text,stage)}</div></div>
       ${stage===1?`<div class="row"><button class="sm" data-act="reziSay">${ic("play")}Vorlesen</button><button class="sm ghost" data-act="reziSlow">Langsam</button></div>`:`<small class="muted ui">${stage===2?"Say each line aloud from the first letters. Tap a word to peek.":"Tap a gap to see the word. Say the whole poem aloud."}</small>`}`
     :`<p class="muted ui">Write it from memory — line breaks don't matter. Or press 🎤 and recite it.</p><textarea class="rz-in" rows="10" placeholder="…"></textarea><div class="row"><button class="go" data-act="reziCheck">Prüfen</button>${"webkitSpeechRecognition" in window||"SpeechRecognition" in window?`<button data-act="reziMic">🎤 Sprechen</button>`:""}</div><div id="rzOut"></div>`}
     <small class="muted ui">${esc(p.a)} · ${esc(p.src)} · gemeinfrei</small></div>`;
    box.querySelectorAll("[data-rs]").forEach(b=>b.onclick=()=>{stage=+b.dataset.rs;SND.fx("page");draw()});
    box.querySelectorAll(".rz-gap").forEach(b=>b.onclick=()=>{b.textContent=b.dataset.w;b.classList.add("on")});box.querySelectorAll(".rz-h").forEach(b=>b.onclick=()=>{b.textContent=b.title})};
  ACT.reziSay=()=>say(p.text.replace(/\n+/g," "),{rate:.9});ACT.reziSlow=()=>say(p.text.replace(/\n+/g," "),{rate:.7});
  ACT.reziCheck=()=>{const v=box.querySelector(".rz-in").value;const d=reziDiff(p.text,v);S.rezi=S.rezi||{};const r=S.rezi[p.id]=S.rezi[p.id]||{best:0};r.best=Math.max(r.best,d.pct);r.last=d.pct;r.d=todayKey();saveSoon();SND.fx(d.pct>=90?"seal":d.pct>=60?"ok":"no");
    $("#rzOut").innerHTML=`<div class="card stack s pk-fade"><h3>${d.pct} % auswendig</h3><div class="no-sig" style="line-height:1.8">${d.A.map((w,i)=>d.hit.has(i)?esc(w):`<b style="color:var(--bad);text-decoration:underline wavy" title="fehlt oder falsch">${esc(w)}</b>`).join(" ")}</div><div class="small muted"><span style="color:var(--bad);text-decoration:underline wavy">rot</span> = fehlt oder falsch geschrieben <span class="en">red = missing or misspelt</span></div>${pkSay(d.pct>=90?["Nicht schlecht. Goethe würde sich im Grab umdrehen – vor Neid.","Not bad. Goethe would turn in his grave — with envy."]:pkMephLine("wrong"))}</div>`};
  ACT.reziMic=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;try{const r=new SR();r.lang="de-DE";r.continuous=true;r.interimResults=false;const ta=box.querySelector(".rz-in");r.onresult=e=>{for(let k=e.resultIndex;k<e.results.length;k++)if(e.results[k].isFinal)ta.value+=(ta.value?" ":"")+e.results[k][0].transcript};r.onerror=()=>toast("Mikrofon nicht verfügbar.");r.start();toast("Sprechen Sie … (Tippen auf Prüfen beendet)",3000);ACT._rzRec=r}catch(e){toast("Spracherkennung nicht verfügbar.")}};
  draw()};
// ---------------------------------------------------------------- 7. Die Bibliothek (public-domain books, graded)
let BIB=null,BIB_P=null;
function bibLoad(){if(BIB)return Promise.resolve(BIB);if(BIB_P)return BIB_P;BIB_P=(async()=>{let bin;if(/\.(bin|json)$/.test(BIB_GZ)){const r=await fetch(BIB_GZ);if(!r.ok)throw new Error("Bibliothek nicht geladen ("+r.status+")");bin=new Uint8Array(await r.arrayBuffer())}else bin=Uint8Array.from(atob(BIB_GZ),c=>c.charCodeAt(0));let txt;if(bin[0]===0x1f&&bin[1]===0x8b){const ds=new DecompressionStream("gzip");txt=await new Response(new Blob([bin]).stream().pipeThrough(ds)).text()}else txt=new TextDecoder().decode(bin);BIB=JSON.parse(txt);BIB.gk=glossKey(BIB.gloss||{});return BIB})();BIB_P.catch(()=>{BIB_P=null});return BIB_P}
function bibKnown(ps){let n=0,k=0;ps.forEach(p=>String(p).replace(/[A-Za-zÄÖÜäöüß]+/g,w=>{n++;const c=DICT[w.toLowerCase()];if(c&&S.cards[c.id])k++;else if(w.length<=3)k++;return w}));return n?Math.round(100*k/n):0}
ACT.bib=()=>{const box=Focus.open({title:"Die Bibliothek",sub:`${BIB_META.length} Bücher · gemeinfrei`});const B=S.bib||{};const lv=typeof learnerLv==="function"?learnerLv():0;
  const groups=[["A1–A2","A1","A2"],["B1","B1"],["B2","B2"],["C1","C1"]];
  box.innerHTML=`<div class="stack" style="max-width:760px;margin:0 auto"><div class="card orn">${pkSay(["Lesen Sie. Viel. Wer nur Vokabeln lernt, kennt Wörter. Wer liest, kennt Deutsch.","Read. A lot. Who only learns vocabulary knows words. Who reads knows German."])}</div>
   <p class="muted ui">Tap any word for its meaning and to add it to your deck. Your level: <b>${LVN[lv]}</b> — start where the book feels slightly too hard (about 85–95 % known words).</p>
   ${groups.map(([name,...L])=>{const bs=BIB_META.filter(b=>L.includes(String(b.lv).slice(0,2)));if(!bs.length)return "";return `<div class="stack s"><div class="eyebrow">${name}</div><div class="bib-grid">${bs.map(b=>{const a=pkArt(b.img);const d=Object.keys((B[b.id]||{}).done||{}).length;return `<button class="bib-book" data-act="bibBook" data-id="${b.id}">${a?`<img src="${a.u}" alt="" class="k-${a.k}">`:""}<span class="in"><span class="chip">${esc(b.lv)}</span><b>${esc(b.t)}</b><small>${esc(b.a)} · ${b.y}</small><small>${b.n} Kapitel · ${Math.round(b.words/1000)}k Wörter${d?` · ${d} gelesen`:""}</small></span></button>`}).join("")}</div></div>`}).join("")}</div>`};
ACT.bibBook=async el=>{const id=el.dataset.id;const m=BIB_META.find(b=>b.id===id);const box=Focus.open({title:m.t,sub:m.a+" · "+m.lv,onClose:()=>ACT.bib()});box.innerHTML=`<p class="muted ui pk-flicker">Das Buch wird aufgeschlagen …</p>`;
  let D;try{D=await bibLoad()}catch(e){box.innerHTML=`<div class="card">Dieser Browser kann die Bibliothek nicht entpacken (DecompressionStream fehlt). Bitte Chrome, Edge, Safari 16.4+ oder Firefox 113+ benutzen.</div>`;return}
  const b=D.books.find(x=>x.id===id);const st=(S.bib||{})[id]||{};
  box.innerHTML=`<div class="stack" style="max-width:720px;margin:0 auto">${pkFig(b.img)}<p class="pk-nar">${esc(b.blurb)}</p>
   <div class="stack s">${b.ch.map((c,i)=>{const done=(st.done||{})[i];const kn=bibKnown(c.p.slice(0,6));return `<button class="row between" style="text-align:left;flex-wrap:nowrap" data-act="bibRead" data-id="${id}" data-i="${i}"><span style="min-width:0">${done?"✓ ":""}<b>${esc(c.t)}</b> <small class="muted ui">· ${c.p.reduce((a,p)=>a+p.split(/\s+/).length,0)} Wörter</small></span><span class="chip" title="known words">${kn} %</span></button>`}).join("")}</div>
   <small class="muted ui">Text: Project Gutenberg (gemeinfrei), Rechtschreibung behutsam modernisiert. % = share of words already in your deck.</small></div>`};
ACT.bibRead=async el=>{const id=el.dataset.id,ci=+el.dataset.i;const D=await bibLoad();const b=D.books.find(x=>x.id===id);const c=b.ch[ci];const box=Focus.open({title:c.t,sub:b.t,onClose:()=>ACT.bibBook({dataset:{id}})});
  const nW=c.p.reduce((a,p)=>a+p.split(/\s+/).length,0);
  box.innerHTML=`<div class="stack bib-text ${b.verse?"verse":""}" style="max-width:680px;margin:0 auto" data-gk="${D.gk}">
    <div class="row between"><small class="muted ui">${nW} Wörter · ca. ${Math.max(1,Math.round(nW/120))} Min. · ${bibKnown(c.p)} % bekannt</small><button class="sm ghost" data-act="bibSayAll">${ic("play")}Alles vorlesen</button></div>
    ${c.p.map((p,i)=>`<div class="bib-p"><p>${b.verse?glossify(p).replace(/\n/g,"<br>"):glossify(p)}</p><button class="sm ghost bib-say" data-k="${i}" aria-label="Vorlesen">${ic("play")}</button></div>`).join("")}
    ${c.q&&c.q.length?`<div class="card stack s"><div class="eyebrow">Fragen zum Text (Guerber, 1896)</div><ol style="margin:0;padding-left:1.2rem">${c.q.map(q=>`<li>${esc(q)}</li>`).join("")}</ol><small class="muted ui">Answer three of them below — out loud first, then in writing.</small></div>`:""}
    <div class="card stack s"><div class="eyebrow">Nacherzählung</div><p class="ui" style="font-size:.92rem">${c.q&&c.q.length?"Beantworte drei Fragen in ganzen Sätzen.":"Erzähle das Kapitel in 4–6 Sätzen nach: Wer? Wo? Was passiert? Was denkst du?"}</p><textarea class="bib-in" rows="5"></textarea><button data-act="bibCheck">Prüfen</button><div id="bibOut"></div></div>
  </div>`;
  box.querySelectorAll(".bib-say").forEach(x=>x.onclick=()=>say(c.p[+x.dataset.k].replace(/\n/g," "),{rate:.9}));
  ACT.bibSayAll=async()=>{for(const p of c.p){const ok=await say(p.replace(/\n/g," "),{rate:.92});if(!ok||!Focus.isOpen())break}};
  ACT.bibCheck=()=>{const v=box.querySelector(".bib-in").value.trim();if(v.length<20)return toast("Ein paar Sätze mehr, bitte.");pkCheck($("#bibOut"),v,{t:"Nacherzählung: "+b.t,task:`Nacherzählung von „${c.t}“ aus ${b.t} (${b.a}). ${c.q?"Antworten auf Fragen zum Text.":""}`,reg:"neutral",check:[]})};
  Focus.foot(`<button class="go" data-act="bibDone">Kapitel gelesen${ci<b.ch.length-1?" · weiter":""}</button>`);
  ACT.bibDone=()=>{S.bib=S.bib||{};const st=S.bib[id]=S.bib[id]||{done:{}};st.done=st.done||{};if(!st.done[ci]){st.done[ci]=todayKey();S.bibWords=(S.bibWords||0)+nW}saveSoon();SND.fx("page");toast(`${nW} Wörter gelesen. Gesamt: ${(S.bibWords||0).toLocaleString("de-DE")}.`,2500);
    if(ci<b.ch.length-1)ACT.bibRead({dataset:{id,i:ci+1}});else{Focus.close(true);ACT.bibBook({dataset:{id}})}}};
// ---------------------------------------------------------------- 8. Medien: what to watch, then retell it
ACT.media=()=>{const box=Focus.open({title:"Kino, Serien & Podcasts",sub:"Schauen · nacherzählen · bewertet"});const M=S.media||{};
  box.innerHTML=`<div class="stack" style="max-width:760px;margin:0 auto"><div class="card orn">${pkSay(["Schauen Sie mit deutschem Ton und deutschen Untertiteln. Englische Untertitel sind Betrug. Ich erkenne Betrug.","Watch with German audio and German subtitles. English subtitles are cheating. I know cheating when I see it."])}</div>
   <p class="muted ui">After watching, write the retell. The coach (or Claude, inside claude.ai or with your API key) grades your German. Mephisto can't watch with you — your retell is the proof.</p>
   ${Object.keys(REALMS).map(r=>{const L=MEDIA.filter(x=>x.r===r);if(!L.length)return "";return `<div class="stack s"><div class="eyebrow">Reich ${r} · ${esc(REALMS[r].de)}</div>${L.map(x=>`<div class="card stack s"><div class="row between" style="align-items:flex-start"><div style="min-width:0"><b style="font-family:var(--body);font-size:1.12rem">${esc(x.t)}</b><br><small class="muted ui">${esc(x.k)} · ${esc(x.lv)} · ${esc(x.where)}</small></div>${M[x.id]?`<span class="chip">✓ ${esc(typeof fmtDate==="function"?fmtDate(M[x.id].d):M[x.id].d)}</span>`:""}</div><p class="ui" style="font-size:.92rem;margin:0">${esc(x.why)}</p>
     <div class="row"><a class="go sm" style="display:inline-flex;align-items:center;padding:.4rem .8rem;border-radius:var(--r-s);text-decoration:none;min-height:38px" href="${esc(MEDIA_SRC[x.src](x.q))}" target="_blank" rel="noopener">Öffnen ↗</a><button class="sm" data-act="mediaRetell" data-id="${x.id}">Nacherzählen</button></div></div>`).join("")}</div>`}).join("")}</div>`};
ACT.mediaRetell=el=>{const x=MEDIA.find(m=>m.id===el.dataset.id);const box=Focus.open({title:x.t,sub:"Nacherzählung",onClose:()=>ACT.media()});const old=(S.media||{})[x.id];
  box.innerHTML=`<div class="stack" style="max-width:640px;margin:0 auto"><div class="card"><div class="eyebrow">Aufgabe</div><p style="font-family:var(--body);font-size:1.1rem;margin:.3rem 0">${esc(x.task)}</p></div><textarea class="md-in" rows="8">${esc(old?old.text:"")}</textarea><button class="go" data-act="mediaCheck">Prüfen & speichern</button><div id="mdOut"></div></div>`;
  ACT.mediaCheck=()=>{const v=box.querySelector(".md-in").value.trim();if(v.length<30)return toast("Mindestens drei Sätze.");S.media=S.media||{};S.media[x.id]={d:todayKey(),text:v};saveSoon();pkCheck($("#mdOut"),v,{t:x.t,task:`Nacherzählung nach dem Anschauen von „${x.t}“ (${x.k}). Aufgabe: ${x.task}`,reg:"neutral",check:[]})}};
