  const initial=(t)=>{const m=t.match(/^([„"»(]*)([A-Za-zÄÖÜäöüß])([A-Za-zÄÖÜäöüß]*)/);if(!m)return glossify(t);const w=m[2]+m[3];return `${esc(m[1])}<span class="w" tabindex="0" data-w="${esc(w)}"><span class="ill">${esc(m[2])}</span>${esc(m[3])}</span>${glossify(t.slice(m[0].length))}`};
