(function(){const _pl=pkLine;pkLine=function(kind,n){const l=_pl(kind,n);try{if(P().du===true&&MEPH_DU[kind]){const L=MEPH[kind]||MEPH.greet;const i=L.findIndex(x=>x[1]===l[1]||String(x[1]).replace("{n}",n!=null?n:"")===l[1]);if(i>=0&&MEPH_DU[kind][i])return [MEPH_DU[kind][i].replace("{n}",n!=null?n:""),l[1]]}}catch(e){}return l}})();
