  const raw=L4.raw&&Date.now()-L4.raw.t<600000?L4.raw.v:"";const why=q>=1?l4Strict(raw,good,it.type):"";if(why){q=0;try{toast(why+" Zählt diesmal nicht.",3800)}catch(e){}}
