function l6DiffHTML(d){return d.out.map(t=>t.st==="ok"?`<span>${esc(t.w)}</span>`:t.st==="case"?`<span class="l6-case" title="Groß/klein">${esc(t.w)}</span>`:t.st==="miss"?`<span class="l6-miss">${esc(t.w)}</span>`:`<s class="l6-extra">${esc(t.w)}</s>`).join(" ")}
