function pick(a,b){if(!Array.isArray(a))return b;if(!Array.isArray(b))return a;if((a[1]|0)!==(b[1]|0))return (a[1]|0)>(b[1]|0)?a:b;if((a[2]|0)!==(b[2]|0))return (a[2]|0)>(b[2]|0)?a:b;return (a[0]||0)>=(b[0]||0)?a:b}
