function pruneDays(m){var cut=dn(today())-400;for(var d in m.d)if(+d<cut)delete m.d[d];var sk=Object.keys(m.sn).map(Number).sort(function(a,b){return a-b});while(sk.length>80)delete m.sn[sk.shift()]}
